(window.EX_CHUNKS=window.EX_CHUNKS||{})["b39"]={"叉子":[["请用叉子把牛排切开来。","پىچاقچە بىلەن بىفشتىكنى كېسىڭ.","pichaqche bilen bifshtikni késing."]],"和平":[["我们热爱和平，坚决反对任何形式的战争。","بىز تىنچلىقنى سۆيىمىز، ھەر قانداق شەكىلدىكى ئۇرۇشقا قەتئىي قارشى تۇرىمىز.","biz tinchliqni söyimiz, her qandaq shekildiki urushqa qet'iy qarshi turimiz."]],"搅拌":[["制作蛋糕时，需要将各种材料充分搅拌。","تورتمەك ياسىغاندا، ھەر خىل ماتېرىياللارنى تولۇق ئارىلاشتۇرۇش كېرەك.","tortmek yasighanda, her xil matériyallarni toluq arilashturush kérek."]],"忌讳":[["有些地方对某些数字有忌讳。","بەزى جايلاردا بەزى سانلاردىن ساقلىنىش بار.","bezi jaylarda bezi sanlardin saqlinish bar."]],"恰到好处":[["他说话恰到好处。","ئۇنىڭ سۆزلىشى دەل مۇۋاپىق.","uning sözlishi del muwapiq."]],"责怪":[["因为迟到，他被老师责怪了一顿。","كېچىككەنلىكى ئۈچۈن، ئۇ ئوقۇتقۇچىسىدىن بىر ئېغىز ئەيىبلەندى.","kéchikkenliki üchün, u oqutquchisidin bir éghiz eyiblendi."]],"佧":[["这种佧纸非常轻薄，容易破损。","بۇ خىل قەغەز ئىنتايىن يۇپقا، ئاسان بۇزۇلىدۇ.","bu xil qeghez intayin yupqa, asan buzulidu."]],"撧":[["他撧了撧手上的泥。","ئۇ قولىدىكى لاينى قاقتى.","u qolidiki layni qaqti."]],"橧":[["橧木适合做建筑材料。","ئۇدۇن ياغىچى قۇرۇلۇش ماتېرىيالى قىلىشقا ماس كېلىدۇ.","udun yaghichi qurulush matériyali qilishqa mas kélidu."]],"汧":[["汧水流域生态良好。","چيەنشۈي دەرياسى ئېقىن رايونىنىڭ ئېكولوگىيىسى ياخشى.","chyenshüy deryasi éqin rayonining ékologiyisi yaxshi."]],"樧":[["樧木的果实可以吃。","بۇ دەرەخنىڭ مېۋىسىنى يېيىشكە بولىدۇ.","bu derexning méwisini yéyishke bolidu."]],"渧":[["雨滴从屋檐落下，形成细密的渧珠。","يامغۇر تام ئاستىدىن تامچىلاپ، زىچ تامچىلار ھاسىل قىلدى.","yamghur tam astidin tamchilap, zich tamchilar hasil qildi."]],"滧":[["滧水从山间缓缓流下。","شياۋشۇي تاغ ئارىسىدىن ئاستا ئېقىپ چۈشمەكتە.","shyawshuy tagh arisidin asta éqip chüshmekte."]],"瑧":[["瑧的画作充满生命力。","جېننىڭ رەسىملىرى ھاياتىي كۈچكە تولغان.","jénning resimliri hayatiy küchke tolghan."]],"礧":[["礧石是古代的建筑材料。","قەدىمكى زاماندا قۇرۇلۇش ماتېرىيالى بولغان.","qedimki zamanda qurulush matériyali bolghan."]],"穧":[["这片田地穧荒多年无人耕作。","بۇ ئېتىز كۆپ يىللاردىن بۇيان تاشلاندۇق ھالەتتە ئىشلەنمەي قالدى.","bu étiz köp yillardin buyan tashlanduq halette ishlenmey qaldi."]],"籧":[["籧竹的叶子很宽大。","چۈ بامبۇكىنىڭ يوپۇرماقلىرى بەك كەڭ.","chü bambukining yopurmaqliri bek keng."]],"蓧":[["蓧草生长在潮湿的河岸上。","ئۇ سۇلۇق دەريا بويىدا ئۆسىدۇ.","u suluq derya boyida ösidu."]],"葧":[["这种葧果口感酸甜可口。","بۇ خىل ئېرىق مېۋىسىنىڭ تەمى ئاچچىق-چۈچۈك ۋە تاتلىق.","bu xil ériq méwisining temi achchiq-chüchük we tatliq."]],"薧":[["这种植物叫薧。","بۇ ئۆسۈملۈك ئوت دەپ ئاتىلىدۇ.","bu ösümlük ot dep atilidu."]],"苧":[["苧布是用苧麻做的。","رىڭ رەختى رىڭ كەندىرىدىن توقۇلغان.","ring rexti ring kendiridin toqulghan."]],"菧":[["她做了菧菜汤，味道鲜美。","ئۇ كۈنچىقار شورپىسى قىلدى، تەمى لەززەتلىك.","u künchiqar shorpisi qildi, temi lezzetlik."]],"褧":[["他穿着褧衣在田里劳作。","ئۇ يېنىك كىيىم كىيىپ ئېتىزدا ئەمگەك قىلدى.","u yénik kiyim kiyip étizda emgek qildi."]],"陧":[["陧坡平缓，适合散步。","تاغ باغرى يېنىك، سەيلە قىلىشقا ماس كېلىدۇ.","tagh baghri yénik, seyle qilishqa mas kélidu."]],"鞧":[["他鞧马时动作非常熟练。","ئۇ ئاتنى ئېگەرلىگەندە ھەرىكىتى ئىنتايىن ماھىر ئىدى.","u atni égerligende herikiti intayin mahir idi."]],"髧":[["他留着髧发，显得十分有个性。","ئۇ چاچلىرىنى تاراملاپ قويغان، ئىنتايىن ئالاھىدە كۆرۈنىدۇ.","u chachlirini taramlap qoyghan, intayin alahide körünidu."]],"齧":[["老鼠在夜里齧咬电线。","چاشقان كېچىسى توك سىمىنى چىشلەيدۇ.","chashqan kéchisi tok simini chishleydu."]],"一对一":[["教练会进行一对一指导。","مەشقاۋۇل بىرگە بىر يېتەكچىلىك قىلىدۇ.","meshqawul birge bir yétekchilik qilidu."]],"一年半载":[["一年半载就能学会这项技能。","بىر يىل يېرىم ئىچىدە بۇ ماھارەتنى ئۆگىنىۋالغىلى بولىدۇ.","bir yil yérim ichide bu maharetni öginiwalghili bolidu."]],"一文不名":[["他刚毕业时，还一文不名，生活十分艰难。","ئۇ ئەمدىلا ئوقۇش پۈتتۈرگەندە، تېخى بىر تىيىنغا ئەرزىمەيتتى، تۇرمۇشى ئىنتايىن قىيىن ئىدى.","u emdila oqush püttürgende, téxi bir tiyingha erzimeytti, turmushi intayin qiyin idi."]],"一定要":[["你一定要按时完成这项任务。","سىز چوقۇم بۇ ۋەزىپىنى ۋاقتىدا ئورۇندىشىڭىز كېرەك.","siz choqum bu wezipini waqtida orundishingiz kérek."]],"一级":[["他通过了一级考试。","ئۇ بىرىنچى دەرىجىلىك ئىمتىھاندىن ئۆتتى.","u birinchi derijilik imtihandin ötti."]],"一日不见，如隔三秋":[["一日不见，如隔三秋。","بىر كۈن كۆرمىسەم، ئۈچ يىل ئايرىلغاندەك بىلىنىدۇ.","bir kün körmisem, üch yil ayrilghandek bilinidu."]],"一时半刻":[["等一时半刻也不难。","بىر ئاز ساقلىسا ئۇزاققا سۈرۈلمەيدۇ.","bir az saqlisa uzaqqa sürülmeydu."]],"一针见血":[["他的批评一针见血，直指问题核心。","ئۇنىڭ تەنقىدى ئىنتايىن ئېنىق، مەسىلىنىڭ يادروسىنى كۆرسىتىپ بەردى.","uning tenqidi intayin éniq, mesilining yadrosini körsitip berdi."]],"一门式":[["这种设计采用了一门式结构。","بۇ خىل لايىھە بىر ئىشىكلىك قۇرۇلمىنى قوللانغان.","bu xil layihe bir ishiklik qurulmini qollanghan."]],"三氯化磷":[["三氯化磷在工业中有广泛应用。","ئۈچ خلورلۇق فوسفور سانائەتتە كەڭ قوللىنىلىدۇ.","üch xlorluq fosfor sanaette keng qollinilidu."]],"三皇五帝":[["三皇五帝是中国古代的重要统治者。","ئۈچ پادىشاھ بەش ئىمپېراتور جۇڭگو قەدىمكى زامانىدىكى مۇھىم ھۆكۈمرانلار.","üch padishah besh impérator junggo qedimki zamanidiki muhim hökümranlar."]],"三磷酸腺苷":[["三磷酸腺苷是细胞中的能量分子。","ئۈچ فوسفاتلىق ئادېنوزىن ھۈجەيرىدىكى ئېنېرگىيە مولېكۇلىسى.","üch fosfatliq adénozin hüjeyridiki énérgiye molékulisi."]],"三个臭皮匠，赛过一个诸葛亮":[["三个臭皮匠，赛过一个诸葛亮，强调团队合作的力量。","ئۈچ دانا كونا كۆنچى بىر جوگېلىاڭدىن ئېشىپ چۈشىدۇ، بۇ گۇرۇپپا ھەمكارلىقىنىڭ كۈچىنى تەكىتلەيدۇ.","üch dana kona könchi bir jogéliangdin éship chüshidu, bu guruppa hemkarliqining küchini tekitleydu."]],"不名一文":[["他身不名一文。","ئۇ بىر تىيىنغىمۇ ئىگە ئەمەس.","u bir tiyinghimu ige emes."]],"下逐客令":[["他当场下逐客令。","ئۇ شۇ يەرنىڭ ئۆزىدە مېھمانلارنى قوغلاپ چىقاردى.","u shu yerning özide méhmanlarni qoghlap chiqardi."]],"下酒":[["这道菜很下酒。","بۇ تائام ئىچىملىككە بەك يارىشىدۇ.","bu taam ichimlikke bek yarishidu."]],"下颌骨":[["下颌骨是面部的重要骨骼。","ئاستىنقى ئېڭەك سۆڭىكى يۈزنىڭ مۇھىم سۆڭىكىدۇر.","astinqi éngek söngiki yüzning muhim söngikidur."]],"不可侵犯权":[["每个人都有不可侵犯权。","ھەر بىر ئادەمنىڭ دەخلى يەتكۈزگىلى بولمايدىغان ھوقۇقى بار.","her bir ademning dexli yetküzgili bolmaydighan hoquqi bar."]],"七上八下":[["他考试前心里七上八下。","ئۇ ئىمتىھاندىن بۇرۇن كۆڭلى بەك ئىشەنچسىز ئىدى.","u imtihandin burun köngli bek ishenchsiz idi."]],"不情愿":[["他很不情愿地接受了这个任务。","ئۇ بۇ ۋەزىپىنى ئىنتايىن خالىسىز قوبۇل قىلدى.","u bu wezipini intayin xalisiz qobul qildi."]],"不拘一格":[["选拔人才应不拘一格。","ئىختىساس ئىگىلىرىنى تاللاشدا بىر ئۆلچەمدە چەكلىنىپ قالماستىن كېرەك.","ixtisas igilirini tallashda bir ölchemde cheklinip qalmastin kérek."]],"不堪忍受":[["这种噪音简直不堪忍受。","بۇ خىل شاۋقۇننى چىدىغىلى بولمايدۇ.","bu xil shawqunni chidighili bolmaydu."]],"不经意间":[["不经意间，天就黑了。","سەزمەيلا ئاسمان قاراڭغۇلاپ قالدى.","sezmeyla asman qarangghulap qaldi."]],"不锈钢":[["这个不锈钢杯子非常耐用。","بۇ داتلاشمايدىغان پولات ئىستاكان ئىنتايىن چىداملىق.","bu datlashmaydighan polat istakan intayin chidamliq."]],"丘县":[["丘县历史悠久，文化深厚。","چيۇ ناھىيىسىنىڭ تارىخى ئۇزۇن، مەدەنىيىتى چوڭقۇر.","chyu nahiyisining tarixi uzun, medeniyiti chongqur."]],"中水":[["中水经过处理后可用于灌溉。","ئوتتۇرا سۇ بىر تەرەپ قىلىنغاندىن كېيىن سۇغىرىشتا ئىشلىتىلىشى مۇمكىن.","ottura su bir terep qilinghandin kéyin sughirishta ishlitilishi mumkin."]],"串行点阵打印机":[["这台串行点阵打印机老旧了。","بۇ تەرتىپلىك نۇقتىلىق پرىنتېر كونا بولۇپ قالدى.","bu tertiplik nuqtiliq printér kona bolup qaldi."]],"鼠标":[["这款鼠标的握感很舒服，不容易累手。","بۇ چاشقىنەكنىڭ تۇتۇش تۇيغۇسى ئىنتايىن راھەت، قولنى ئاسان چارچىتمايدۇ.","bu chashqinekning tutush tuyghusi intayin rahet, qolni asan charchitmaydu."]],"中华仙鹟":[["中华仙鹟是一种珍稀鸟类。","جۇڭخۇا سەۋزە قۇشى ناھايىتى كام ئۇچرايدىغان قۇش تۈرى.","jungxua sewze qushi nahayiti kam uchraydighan qush türi."]],"中华龙鸟":[["中华龙鸟是恐龙的祖先。","جۇڭخۇا ئەجدەرھا قۇشى دىنوزاۋرلارنىڭ ئەجدادىدۇر.","jungxua ejderha qushi dinozawrlarning ejdadidur."]],"中巴":[["中巴两国正在加强基础设施建设合作。","جۇڭگو بىلەن پاكىستان ئىككى دۆلەت ئاساسىي قۇرۇلۇش تەرەققىيات ھەمكارلىقىنى كۈچەيتىۋاتىدۇ.","junggo bilen pakistan ikki dölet asasiy qurulush tereqqiyat hemkarliqini kücheytiwatidu."]],"乘便":[["他乘便把东西都整理得井井有条。","ئۇ پۇرسەتنى غەنىيمەت بىلىپ، ھەممە نەرسىنى تەرتىپكە سېلىپ قويدى.","u pursetni gheniymet bilip, hemme nersini tertipke sélip qoydi."]],"九台区":[["九台区位于吉林省长春市。","جۇتەي رايونى جىلىن ئۆلكىسى چاڭچۈن شەھىرىدە جايلاشقان.","jutey rayoni jilin ölkisi changchün shehiride jaylashqan."]],"乳腺":[["乳腺负责分泌乳汁。","سۈت بېزى سۈت ئاجرىتىشقا مەسئۇل.","süt bézi süt ajritishqa mes'ul."]],"二尕子":[["二尕子是对家中第二个儿子的称呼。","ئىككىنچى گازا ئائىلىدىكى ئىككىنچى ئوغۇلنىڭ ئاتىلىشىدۇر.","ikkinchi gaza ailidiki ikkinchi oghulning atilishidur."]],"五花大绑":[["五花大绑指将人手脚捆绑的束缚方式。","بەش گۈللۈك چىڭ باغلاش ئادەمنىڭ قول-پۇتىنى باغلايدىغان چەكلەش ئۇسۇلىنى كۆرسىتىدۇ.","besh güllük ching baghlash ademning qol-putini baghlaydighan cheklesh usulini körsitidu."]],"井然有序":[["会议进行得井然有序。","يىغىن تەرتىپلىك ئېلىپ بېرىلدى.","yighin tertiplik élip bérildi."]],"交友":[["他善于交友，人缘很好。","ئۇ دوست تۇتۇشقا ماھىر، كىشىلەر ئارىسىدا ئابرويى ياخشى.","u dost tutushqa mahir, kishiler arisida abroyi yaxshi."]],"亚铁":[["亚铁离子在化学反应中常作为还原剂。","تۆمۈر(II) ئىونى خىمىيىلىك رېئاكسىيەلەردە كۆپىنچە قايتۇرغۇچى رولىنى ئوينايدۇ.","tömür(II) ioni ximiyilik réaksiyelerde köpinche qayturghuchi rolini oynaydu."]],"交易市场":[["交易市场反映了供需关系。","سودا بازىرى تەمىنلەش-تەلەپ مۇناسىۋىتىنى ئەكس ئەتتۈرىدۇ.","soda baziri teminlesh-telep munasiwitini eks ettüridu."]],"交杯酒":[["新人交换交杯酒象征结合。","يېڭى توي قىلغۇچىلار قول تۇتۇشۇپ شاراب ئىچىشى بىرلىشىشنى سىمۋوللايدۇ.","yéngi toy qilghuchilar qol tutushup sharab ichishi birlishishni simwollaydu."]],"亨氏":[["亨氏是一家知名的食品公司。","ھېنز تونۇلغان بىر يېمەكلىك شىركىتى.","hénz tonulghan bir yémeklik shirkiti."]],"京津冀":[["京津冀一体化是中国北方重要的区域发展战略。","جىڭ-جىن-جى بىر گەۋدىلىشىش جۇڭگونىڭ شىمالىدىكى مۇھىم رايون تەرەققىيات ئىستراتېگىيەسى.","jing-jin-ji bir gewdilishish junggoning shimalidiki muhim rayon tereqqiyat istratégiyesi."]],"京沪高铁":[["京沪高铁连接北京和上海，全程约4.5小时。","جىڭ-خۇ يۇقىرى سۈرئەتلىك تۆمۈريولى بېيجىڭ بىلەن شاڭخەينى تۇتاشتۇرىدۇ، پۈتۈن مۇساپە تەخمىنەن 4.5 سائەت.","jing-xu yuqiri sür'etlik tömüryoli béyjing bilen shangxeyni tutashturidu, pütün musape texminen 4.5 saet."]],"人口数":[["最新数据显示，人口数持续增长。","ئەڭ يېڭى سانلىق مەلۇماتلار نۇپۇس سانىنىڭ داۋاملىق ئېشىۋاتقانلىقىنى كۆرسىتىدۇ.","eng yéngi sanliq melumatlar nupus sanining dawamliq éshiwatqanliqini körsitidu."]],"代罪":[["他自愿代罪受罚。","ئۇ ئۆز ئىختىيارى بىلەن جازانى ۋاكالەتەن تارتىلدى.","u öz ixtiyari bilen jazani wakaleten tartildi."]],"介质访问控制层":[["介质访问控制层负责管理网络通信。","ۋاسىتە زىيارەت كونترول قەۋىتى تور ئالاقىسىنى باشقۇرۇشقا مەسئۇل.","wasite ziyaret kontrol qewiti tor alaqisini bashqurushqa mes'ul."]],"他国":[["他国对这一政策表示强烈反对。","ئۇ دۆلەت بۇ سىياسەتكە قەتئىي قارشىلىق بىلدۈردى.","u dölet bu siyasetke qet'iy qarshiliq bildürdi."]],"他山之石可以攻玉":[["他山之石可以攻玉，借鉴他人经验很重要。","باشقا تاغنىڭ تېشى بىلەن ياقۇت ياسىغىلى بولىدۇ، باشقىلارنىڭ تەجرىبىسىدىن ئۆگىنىش مۇھىم.","bashqa taghning téshi bilen yaqut yasighili bolidu, bashqilarning tejribisidin öginish muhim."]],"仰仗":[["我们仰仗团队的努力取得成功。","بىز كوماندىنىڭ تىرىشچانلىقىغا تايىنىپ مۇۋەپپەقىيەت قازاندۇق.","biz komandining tirishchanliqigha tayinip muweppeqiyet qazanduq."]],"佩兰":[["这款佩兰酒口感独特，香气浓郁。","بۇ پېرلان شارابىنىڭ تەمى ئالاھىدە، ھىدى ئېغىر.","bu pérlan sharabining temi alahide, hidi éghir."]],"佩饰":[["她佩戴的佩饰精致而富有艺术感。","ئۇ تاقىغان زىننەت بۇيۇملىرى نەپىس ۋە سەنئەت تۇيغۇسىغا باي.","u taqighan zinnet buyumliri nepis we sen'et tuyghusigha bay."]],"侉子":[["这个侉子说话总是阴阳怪气。","بۇ يات ئادەم سۆزلىگەندە ھەمىشە ئاھاڭى ئېغىر.","bu yat adem sözligende hemishe ahangi éghir."]],"侍应":[["侍应生服务很周到。","مۇلازىمەتچىنىڭ مۇلازىمىتى بەك ئىنچىكە.","mulazimetchining mulazimiti bek inchike."]],"便盆":[["这个便盆适合老年人使用。","بۇ ھاجەت دانىسى ياشانغانلارغا ئىشلىتىشكە ماس كېلىدۇ.","bu hajet danisi yashanghanlargha ishlitishke mas kélidu."]],"使领官员":[["使领官员负责处理外交事务。","ئەلچىلىك ئەمەلدارلىرى دىپلوماتىيە ئىشلىرىنى بىر تەرەپ قىلىشقا مەسئۇل.","elchilik emeldarliri diplomatiye ishlirini bir terep qilishqa mes'ul."]],"倍塔":[["这款手机搭载了最新的倍塔处理器。","بۇ تېلېفون ئەڭ يېڭى بېتا بىر تەرەپ قىلغۇچ بىلەن جابدۇلغان.","bu téléfon eng yéngi béta bir terep qilghuch bilen jabdulghan."]],"仓庚":[["仓庚即黄莺鸟。","ئامبار قۇشى دېگەنلىك سېرىق قۇش.","ambar qushi dégenlik sériq qush."]],"偶然性":[["偶然性在概率学中非常重要。","تاسادىپىيلىق ئېھتىماللىق نەزەرىيەسىدە ئىنتايىن مۇھىم.","tasadipiyliq éhtimalliq nezeriyeside intayin muhim."]],"倥偬":[["他生活得十分倥偬。","ئۇ ناھايىتى ئالدىراش تۇرمۇش كەچۈرىدۇ.","u nahayiti aldirash turmush kechüridu."]],"催乳激素":[["催乳激素促进乳汁分泌。","سۈت ئاجىتىش ھورمونى سۈت ئاجىرىلىشىنى ئىلگىرى سۈرىدۇ.","süt ajitish hormoni süt ajirilishini ilgiri süridu."]],"传输服务":[["提供高效传输服务。","يۇقىرى ئۈنۈملۈك يەتكۈزۈش مۇلازىمىتى تەمىنلەڭ.","yuqiri ünümlük yetküzüsh mulazimiti teminleng."]],"像片簿":[["这本像片簿记录了许多回忆。","بۇ سۈرەت ئالبومى كۆپ ئەسلىمىلەرنى خاتىرىلىگەن.","bu süret albomi köp eslimilerni xatiriligen."]],"伤筋动骨":[["这次事故伤筋动骨，恢复缓慢。","بۇ ھادىسە سۆڭەك-گۆشىگە زىيان يەتكۈزۈپ، ئەسلىگە كېلىش ئاستا بولدى.","bu hadise söngek-göshige ziyan yetküzüp, eslige kélish asta boldi."]],"俭朴":[["俭朴的生活令人敬佩。","تېجەشچان تۇرمۇش كىشىلەرنى ھۆرمەتكە سازاۋەر قىلىدۇ.","téjeshchan turmush kishilerni hörmetke sazawer qilidu."]],"储藏":[["这家商店专门储藏稀有物品。","بۇ دۇكان ناھايىتى ئاز ئۇچرايدىغان بۇيۇملارنى ئالاھىدە ساقلايدۇ.","bu dukan nahayiti az uchraydighan buyumlarni alahide saqlaydu."]],"光源":[["灯泡是常见的光源之一。","لامپۇچكا ئادەتتىكى نۇر مەنبەلىرىنىڭ بىرىدۇر.","lampuchka adettiki nur menbelirining biridur."]],"兑付":[["债券到期后需要兑付。","ئوبليگاتسىيە مۇددىتى توشقاندىن كېيىن تۆلەشكە تېگىشلىك.","oblygatsiye mudditi toshqandin kéyin töleshke tégishlik."]],"两下":[["轻轻两下就修好了。","ئاستا ئىككى قېتىملا رېمونت قىلىپ بولدى.","asta ikki qétimla rémont qilip boldi."]],"两宋":[["两宋时期是中国历史上的重要阶段。","ئىككى سۇڭ دەۋرى جۇڭگو تارىخىدىكى مۇھىم بىر باسقۇچ.","ikki sung dewri junggo tarixidiki muhim bir basquch."]],"两小无猜":[["他们从小一起长大，两小无猜。","ئۇلار كىچىكىدىن بىللە چوڭ بولغان، ئىككى كىچىك بالا ئارىسىدا ھېچقانداق گۇمان يوق.","ular kichikidin bille chong bolghan, ikki kichik bala arisida héchqandaq guman yoq."]],"克里木":[["克里木的历史可以追溯到古代。","كرىم تارىخى قەدىمكى زامانلارغا تۇتىشىدۇ.","krim tarixi qedimki zamanlargha tutishidu."]],"免赔":[["保险包含免赔条款。","سۇغۇرتا مەسئۇلىيەتتىن قۇتۇلدۇرۇش ماددىسىنى ئۆز ئىچىگە ئالىدۇ.","sughurta mes'uliyettin qutuldurush maddisini öz ichige alidu."]],"八宝丹":[["八宝丹是一种传统的中药配方。","باباۋدان ئەنئەنىۋى جۇڭگو تېبابىتىنىڭ بىر خىل رېتسېپى.","babawdan en'eniwi junggo tébabitining bir xil rétsépi."]],"八纲":[["八纲是中医诊断的基本原则。","سەككىز پرىنسىپ جۇڭگو تېبابىتى دىئاگنوزىنىڭ ئاساسىي پرىنسىپىدۇر.","sekkiz prinsip junggo tébabiti diagnozining asasiy prinsipidur."]],"公墓":[["公墓是安葬逝者的场所。","ئورتاق قەبرىستانلىق ۋاپات بولغانلارنى دەپنە قىلىدىغان جايدۇر.","ortaq qebristanliq wapat bolghanlarni depne qilidighan jaydur."]],"八冲":[["八冲是古代兵器中的一种。","سەككىز ئوق قەدىمكى قوراللارنىڭ بىرى.","sekkiz oq qedimki qorallarning biri."]],"六氟化硫":[["六氟化硫是重要气体。","كۈمۈش ئالتى فلورىدى مۇھىم گازدۇر.","kümüsh alti floridi muhim gazdur."]],"再制盐":[["再制盐的纯度达到了工业标准。","قايتا ئىشلەنگەن تۇزنىڭ ساپلىقى سانائەت ئۆلچىمىگە يەتتى.","qayta ishlengen tuzning sapliqi sanaet ölchimige yetti."]],"兵强马壮":[["军队兵强马壮，战无不胜。","ئارمىيەنىڭ ئەسكەرلىرى كۈچلۈك، ئاتلىرى سېمىز، ئۇرۇشتا ھەرگىز مەغلۇب بولمايدۇ.","armiyening eskerliri küchlük, atliri sémiz, urushta hergiz meghlub bolmaydu."]],"凌河":[["凌河是一条重要的河流。","لىڭخې ئېقىنى مۇھىم بىر دەريا.","lingxé éqini muhim bir derya."]],"出租司机":[["出租司机很热情。","ئىجارە شوپۇرى ئىنتايىن ئىللىق.","ijare shopuri intayin illiq."]],"出殡":[["出殡仪式在清晨举行。","دەپنە مۇراسىمى سەھەردە ئۆتكۈزۈلدى.","depne murasimi seherde ötküzüldi."]],"出没":[["深夜常有野兽出没。","چوڭقۇر كېچىدە دائىم ياۋايى ھايۋانلار چىقىپ يۈرىدۇ.","chongqur kéchide daim yawayi haywanlar chiqip yüridu."]],"刑拘":[["他被依法刑拘。","ئۇ قانۇن بويىچە جىنايى تۇتۇشقا ئېلىندى.","u qanun boyiche jinayi tutushqa élindi."]],"划船":[["我们一起去划船吧。","بىز بىرلىكتە كېمە ئېشىپ كېلەيلى.","biz birlikte kéme éship kéleyli."]],"冰块":[["冰块融化后会让饮料变淡。","مۇز پارچىلىرى ئېرىگەندىن كېيىن ئىچىملىكنى تەمىنى سۇسلىتىدۇ.","muz parchiliri érigendin kéyin ichimlikni temini suslitidu."]],"冰店":[["冰店里的冰淇淋口感细腻。","مۇز دۇكىنىدىكى مۇزقايماق تەمى نەپىس.","muz dukinidiki muzqaymaq temi nepis."]],"冰斗":[["冰斗是冰川侵蚀形成的洼地。","مۇز چۆكمىسى مۇز دەرياسىنىڭ ئېرىشىدىن شەكىللەنگەن پاتقاق.","muz chökmisi muz deryasining érishidin shekillengen patqaq."]],"判例":[["这个判例影响深远。","بۇ سوت ئەمەلىيىتىنىڭ تەسىرى چوڭقۇر.","bu sot emeliyitining tesiri chongqur."]],"到得":[["他到得时候已经天黑了。","ئۇ يەتكەندە ئاللىقاچان قاراڭغۇ بولۇپ قالغان ئىدى.","u yetkende alliqachan qarangghu bolup qalghan idi."]],"则辣黑":[["则辣黑是一种传统饮品。","زەلەخ بىر خىل ئەنئەنىۋى ئىچىملىكتۇر.","zelex bir xil en'eniwi ichimliktur."]],"剖白":[["小说中的人物剖白了内心矛盾。","روماندا كىشىلەرنىڭ ئىچكى زىددىيىتى ئېچىپ بېرىلدى.","romanda kishilerning ichki ziddiyiti échip bérildi."]],"副驾驶":[["副驾驶坐在驾驶员旁边协助操作。","مۇئاۋىن شوپۇر شوپۇرنىڭ يېنىدا ئولتۇرۇپ مەشغۇلاتقا ياردەملىشىدۇ.","muawin shopur shopurning yénida olturup meshghulatqa yardemlishidu."]],"力波":[["力波是音乐中的术语之一。","لىبو مۇزىكىدىكى ئاتالغۇلارنىڭ بىرى.","libo muzikidiki atalghularning biri."]],"剪辑":[["剪辑是视频制作的重要环节。","قىرقىش سىن ئىشلەشتە مۇھىم بىر ھالقا.","qirqish sin ishleshte muhim bir halqa."]],"勇气可嘉":[["她的勇气可嘉，令人感动。","ئۇنىڭ جۈرئىتى تەستىققا سازاۋەر، كىشىنى تەسىرلەندۈرىدۇ.","uning jür'iti testiqqa sazawer, kishini tesirlendüridu."]],"勐海":[["勐海是云南省的一个县。","مېڭخەي يۇننەن ئۆلكىسىدىكى بىر ناھىيە.","méngxey yunnen ölkisidiki bir nahiye."]],"勒威耶":[["勒威耶是法国的一位画家。","لېۋېررىيە فرانسىيەدىكى بىر رەسسامدۇر.","léwérriye fransiyediki bir ressamdur."]],"勤劳致富":[["勤劳致富是传统美德。","ئەمگەكچانلىق بىلەن بېيىش ئەنئەنىۋى ئەخلاقتۇر.","emgekchanliq bilen béyish en'eniwi exlaqtur."]],"勤王":[["古人勤王，保卫国家。","قەدىمكىلەر پادىشاھقا تىرىشچانلىق بىلەن خىزمەت قىلىپ، دۆلەتنى قوغدايتتى.","qedimkiler padishahqa tirishchanliq bilen xizmet qilip, döletni qoghdaytti."]],"助动车":[["他骑着一辆老旧的助动车上班。","ئۇ كونا بىر ياردەمچى موتورلۇق ئاپتوموبىل مىنىپ ئىشخانىغا بارىدۇ.","u kona bir yardemchi motorluq aptomobil minip ishxanigha baridu."]],"动量":[["动量是物理学中的基本概念。","ھەرىكەت مىقدارى فىزىكىدىكى ئاساسىي ئۇقۇم.","heriket miqdari fizikidiki asasiy uqum."]],"包退换":[["这家店支持包退换服务。","بۇ دۇكان قايتۇرۇش ۋە ئالماشتۇرۇش مۇلازىمىتىنى قوللايدۇ.","bu dukan qayturush we almashturush mulazimitini qollaydu."]],"化学比色法":[["化学比色法用于检测溶液浓度。","خىمىيىلىك رەڭ سېلىشتۇرما ئۇسۇلى ئېرىتمە قويۇقلۇقىنى ئۆلچەشكە ئىشلىتىلىدۇ.","ximiyilik reng sélishturma usuli éritme qoyuqluqini ölcheshke ishlitilidu."]],"劳心苦思":[["他劳心苦思，终于找到了答案。","ئۇ ئەقلى-ھۇشىنى سەرپ قىلىپ ئويلىنىپ، ئاخىرى جاۋابنى تېپىلدى.","u eqli-hushini serp qilip oylinip, axiri jawabni tépildi."]],"匣枪":[["匣枪是一种早期的火器。","قۇتا مىلتىقى بىر خىل دەسلەپكى ئوت قورالى.","quta miltiqi bir xil deslepki ot qorali."]],"北非":[["北非地区气候炎热干燥。","شىمالىي ئافرىقا رايونىنىڭ ھاۋاسى ئىسسىق ۋە قۇرغاق.","shimaliy afriqa rayonining hawasi issiq we qurghaq."]],"北洋系":[["北洋系在政坛上拥有广泛影响力。","شىمالىي ئوكيان تۈرى سىياسىي سەھنىدە كەڭ تەسىر كۈچىگە ئىگە.","shimaliy okyan türi siyasiy sehnide keng tesir küchige ige."]],"南州":[["南州是一个历史悠久的古城。","نەنجۇ ئۇزۇن تارىخقا ئىگە قەدىمىي شەھەر.","nenju uzun tarixqa ige qedimiy sheher."]],"千禧一代":[["千禧一代人成长在信息爆炸的时代。","مىڭ يىللىق ئەۋلاد ئۇچۇر پارتلىشى دەۋرىدە ئۆسۈپ يېتىلدى.","ming yilliq ewlad uchur partlishi dewride ösüp yétildi."]],"北斗镇":[["北斗镇以农业闻名。","بېيدۇ بازىرى يېزا ئىگىلىكى بىلەن داڭلىقتۇر.","béydu baziri yéza igiliki bilen dangliqtur."]],"厚生劳动省":[["厚生劳动省负责社会保障事务。","ئىجتىمائىي كاپالەت ئىشلىرىنى ساغلاملىق، ئەمگەك ۋە پاراۋانلىق مىنىستىرلىقى مەسئۇل بولىدۇ.","ijtimaiy kapalet ishlirini saghlamliq, emgek we parawanliq ministirliqi mes'ul bolidu."]],"参天":[["那棵古树参天而立。","ئۇ قەدىمىي دەرەخ ئاسمانغا بويلاپ تىك تۇرۇپتۇ.","u qedimiy derex asmangha boylap tik turuptu."]],"反映论":[["反映论探讨认知过程。","ئەكس ئەتتۈرۈش نەزەرىيىسى بىلىش جەريانىنى تەتقىق قىلىدۇ.","eks ettürüsh nezeriyisi bilish jeryanini tetqiq qilidu."]],"反比":[["这个反比关系令人费解。","بۇ قايتۇرما نىسبەت مۇناسىۋىتى كىشىنى ھەيران قالدۇرىدۇ.","bu qayturma nisbet munasiwiti kishini heyran qalduridu."]],"友邦保险":[["友邦保险服务周到可靠。","دوست دۆلەت سۇغۇرتىسى مۇلازىمىتى ئەتراپلىق ۋە ئىشەنچلىك.","dost dölet sughurtisi mulazimiti etrapliq we ishenchlik."]],"参加者":[["所有参加者都签署了协议。","بارلىق قاتناشقۇچىلار كېلىشىمگە ئىمزا قويدى.","barliq qatnashquchilar kélishimge imza qoydi."]],"即为":[["此举即为帮助他人。","بۇ ھەرىكەت باشقىلارغا ياردەم قىلىش ئۈچۈندۇر.","bu heriket bashqilargha yardem qilish üchündur."]],"受试者":[["受试者需签署同意书。","سىناق قاتناشقۇچىسى چوقۇم قوشۇلۇش ھۆججىتىگە ئىمزا قويۇشى كېرەك.","sinaq qatnashquchisi choqum qoshulush höjjitige imza qoyushi kérek."]],"口是心非":[["他口是心非，说的话不可信。","ئۇ ئاغزى بىلەن كۆڭلى باشقا، ئۇنىڭ سۆزىگە ئىشەنگىلى بولمايدۇ.","u aghzi bilen köngli bashqa, uning sözige ishengili bolmaydu."]],"可溶":[["这种物质完全可溶。","بۇ خىل ماددا پۈتۈنلەي ئېرىيدۇ.","bu xil madda pütünley ériydu."]],"古墓葬群":[["古墓葬群规模宏大，令人震撼。","قەدىمكى قەبرىلەر توپى كۆلىمى زور بولۇپ، كىشىنى ھەيران قالدۇرىدۇ.","qedimki qebriler topi kölimi zor bolup, kishini heyran qalduridu."]],"古晋":[["古晋是马来西亚的重要城市。","كۇچىڭ مالايسىيانىڭ مۇھىم شەھىرى.","kuching malaysiyaning muhim shehiri."]],"史莱姆":[["史莱姆是一种黏糊糊的虚构生物。","شىلەيم بىر يېپىشقاق خىيالىي مەخلۇق.","shileym bir yépishqaq xiyaliy mexluq."]],"句法意识":[["良好的句法意识是写作的基础。","ياخشى جۈملە قۇرۇلمىسى تەسەۋۋۇرى يېزىشنىڭ ئاساسى.","yaxshi jümle qurulmisi tesewwuri yézishning asasi."]],"史诗般":[["他的成就堪称史诗般伟大。","ئۇنىڭ نەتىجىسى داستانلىق دەرىجىدە ئۇلۇغ دەپ ئاتىلىشقا لايىق.","uning netijisi dastanliq derijide ulugh dep atilishqa layiq."]],"各别":[["各别情况需要单独处理。","ئايرىم ئەھۋاللارنى ئايرىم بىر تەرەپ قىلىش كېرەك.","ayrim ehwallarni ayrim bir terep qilish kérek."]],"合众国际社":[["合众国际社报道了这起事件。","بىرلەشمە خەلقئارا ئاگېنتلىقى بۇ ۋەقەنى خەۋەر قىلدى.","birleshme xelq'ara agéntliqi bu weqeni xewer qildi."]],"吊嗓子":[["演员每天坚持吊嗓子，以保持嗓音。","ئارتىسلار ھەر كۈنى ئاۋازىنى ئاچىش مەشىقىنى داۋاملاشتۇرۇپ، ئاۋازىنى ساقلايدۇ.","artislar her küni awazini achish meshiqini dawamlashturup, awazini saqlaydu."]],"同盟会":[["同盟会是推翻清朝的重要组织。","ئىتتىپاق جەمئىيىتى چىڭ سۇلالىسىنى ئاغدۇرۇشتا مۇھىم تەشكىلات ئىدى.","ittipaq jem'iyiti ching sulalisini aghdurushta muhim teshkilat idi."]],"吟哦":[["他吟哦着古老的诗句。","ئۇ قەدىمكى شېئىرلارنى ئاۋازلاپ ئوقۇۋاتاتتى.","u qedimki shéirlarni awazlap oquwatatti."]],"合成代谢":[["合成代谢是生物体的过程。","ئانابولىزم بىئولوگىيەلىك جىسىملارنىڭ جەريانى.","anabolizm biologiyelik jisimlarning jeryani."]],"同步口译":[["同步口译要求译员即时传达演讲内容。","قەدەمداش ئاغزاكى تەرجىمە تەرجىماننىڭ نۇتۇق مەزمۇنىنى دەرھال يەتكۈزۈشىنى تەلەپ قىلىدۇ.","qedemdash aghzaki terjime terjimanning nutuq mezmunini derhal yetküzüshini telep qilidu."]],"周口市":[["周口市位于河南省东南部。","جۇكۇ شەھىرى خېنەن ئۆلكىسىنىڭ شەرقىي جەنۇبىدا جايلاشقان.","juku shehiri xénen ölkisining sherqiy jenubida jaylashqan."]],"周永康":[["周永康曾担任重要职务。","جۇ يۇڭكاڭ ئىلگىرى مۇھىم ۋەزىپە ئۆتىگەن.","ju yungkang ilgiri muhim wezipe ötigen."]],"吹胀":[["气球被吹胀了。","شار پۈۋلەپ شىشىرىلدى.","shar püwlep shishirildi."]],"和音":[["这首歌曲的和音非常和谐。","بۇ ناخشىنىڭ ئاھاڭداشلىقى ئىنتايىن ئىناق.","bu naxshining ahangdashliqi intayin inaq."]],"哈伯":[["哈伯是一位著名的科学家。","ھابېر مەشھۇر ئالىم.","habér meshhur alim."]],"名衔":[["他拥有多个名衔。","ئۇ نۇرغۇن ئۇنۋانلارغا ئىگە.","u nurghun unwanlargha ige."]],"哥们":[["哥们儿，今天一起吃饭吧！","ئاكا-ئۇكا، بۈگۈن بىرگە تاماق يەيلى!","aka-uka, bügün birge tamaq yeyli!"]],"哥伦比亚":[["哥伦比亚是南美洲的国家。","كولۇمبىيە جەنۇبىي ئامېرىكىدىكى بىر دۆلەت.","kolumbiye jenubiy amérikidiki bir dölet."]],"唉姐":[["唉姐，你最近过得怎么样？","ئەھە، ئاچا، يېقىندا ئەھۋالىڭىز قانداق؟","ehe, acha, yéqinda ehwalingiz qandaq?"]],"咪唑":[["这种咪唑化合物在化学实验中很常见。","بۇ خىل ئىمىدازول بىرىكمىسى خىمىيە تەجرىبىلىرىدە بەك ئۇچرايدۇ.","bu xil imidazol birikmisi ximiye tejribiliride bek uchraydu."]],"品月":[["品月茶园的茶叶香气浓郁。","پىن يۈە چاي باغچىسىنىڭ چېيىنىڭ ھىدى ئېغىر.","pin yüe chay baghchisining chéyining hidi éghir."]],"唐海":[["唐海是一个沿海城市。","تاڭخەي دېڭىز بويىدا جايلاشقان بىر شەھەر.","tangxey déngiz boyida jaylashqan bir sheher."]],"咕噜":[["他咕噜咕噜地喝完了汤。","ئۇ شورپىنى غۇرۇلدىتىپ ئىچىپ تۈگەتتى.","u shorpini ghurulditip ichip tügetti."]],"哈里发塔":[["哈里发塔是迪拜的标志性建筑。","خەلىپە مۇنارى دۇبەيىنىڭ بەلگىلىك بىناسى.","xelipe munari dubeyining belgilik binasi."]],"哐啷":[["碗掉在地上，哐啷一声碎了。","چىنە يەرگە چۈشۈپ، گۈرۈلدەپ چېقىلىپ كەتتى.","chine yerge chüshüp, gürüldep chéqilip ketti."]],"唱诗班":[["唱诗班的歌声很优美。","ناخشا ئوقۇش گۇرۇپپىسىنىڭ ناخشا ئاۋازى ئىنتايىن گۈزەل.","naxsha oqush guruppisining naxsha awazi intayin güzel."]],"喝令":[["将军喝令士兵立即出发。","گېنېرال ئەسكەرلەرگە دەرھال يولغا چىقىشنى بۇيرۇدى.","général eskerlerge derhal yolgha chiqishni buyrudi."]],"乔治":[["乔治是个友善的人。","جورج ئاق كۆڭۈل ئادەم.","jorj aq köngül adem."]],"喜跃":[["孩子们听到消息后喜跃起来。","بالىلار خەۋەرنى ئاڭلىغاندىن كېيىن خۇشاللىقىدىن سەكرەپ كەتتى.","balilar xewerni anglighandin kéyin xushalliqidin sekrep ketti."]],"单层塔":[["单层塔比多层塔更稳固。","بىر قەۋەتلىك مۇنار كۆپ قەۋەتلىك مۇناردىن تېخىمۇ مۇستەھكەم.","bir qewetlik munar köp qewetlik munardin téximu mustehkem."]],"单模光纤":[["单模光纤传输距离更远。","يالغۇز مودېللىق ئوپتىكىلىق تالا ئۇزۇنراق مۇساپىگە يەتكۈزىدۇ.","yalghuz modélliq optikiliq tala uzunraq musapige yetküzidu."]],"喷雾":[["喷雾能均匀覆盖表面。","سۇ پۈركۈش يۈزنى تەكشى قاپلىيالايدۇ.","su pürküsh yüzni tekshi qapliyalaydu."]],"器质性":[["这种疾病的器质性原因尚未明确。","بۇ كېسەللىكنىڭ ئورگان خاراكتېرلىك سەۋەبى تېخى ئېنىق ئەمەس.","bu késellikning organ xaraktérlik sewebi téxi éniq emes."]],"器量":[["宰相肚里能撑船，可见其器量之大。","ۋەزىرنىڭ قارنىدا كېمە يۈزدۈرگىلى بولىدۇ، بۇنىڭدىن ئۇنىڭ كەڭ قورساقلىقىنى كۆرۈشكە بولىدۇ.","wezirning qarnida kéme yüzdürgili bolidu, buningdin uning keng qorsaqliqini körüshke bolidu."]],"严冬":[["严冬里，人们穿上了厚厚的棉衣。","قاتتىق قىشتا كىشىلەر قېلىن پاختا كىيىم كىيدى.","qattiq qishta kishiler qélin paxta kiyim kiydi."]],"嗉子":[["嗉子用来盛放食物，方便携带。","يېمەكلىك خالتىسى يېمەكلىك ساقلاشقا ئىشلىتىلىدۇ، ئېلىپ يۈرۈشكە قولايلىق.","yémeklik xaltisi yémeklik saqlashqa ishlitilidu, élip yürüshke qolayliq."]],"四方步":[["他迈着四方步，显得格外稳健。","ئۇ تۆت تەرەپلىمە ئۇزۇن قەدەم تاشلاپ، ئىنتايىن مۇقىم كۆرۈندى.","u töt tereplime uzun qedem tashlap, intayin muqim köründi."]],"圉限":[["圉限指的是马场的边界。","ئات مەيدانى چېگرىسى ئات مەيدانىنىڭ چېگرىسىنى كۆرسىتىدۇ.","at meydani chégrisi at meydanining chégrisini körsitidu."]],"国家电力监管委员会":[["国家电力监管委员会负责监管电力行业。","دۆلەت ئېلېكتر ئېنېرگىيە نازارەت كومىتېتى ئېلېكتر ئېنېرگىيە كەسپىنى نازارەت قىلىشقا مەسئۇل.","dölet éléktr énérgiye nazaret komitéti éléktr énérgiye kespini nazaret qilishqa mes'ul."]],"国家一级保护":[["大熊猫是国家一级保护动物。","چوڭ پاندا دۆلەت بىرىنچى دەرىجىلىك قوغدىلىدىغان ھايۋان.","chong panda dölet birinchi derijilik qoghdilidighan haywan."]],"圆石头":[["圆石头被河水打磨得光滑。","يۇمىلاق تاش دەريا سۈيىدە سىلىقلانغان.","yumilaq tash derya süyide siliqlanghan."]],"圆珠形离子交换剂":[["这种圆珠形离子交换剂效果显著。","بۇ خىل يۇمىلاق مارجان شەكىللىك ئىئون ئالماشتۇرغۇچىنىڭ ئۈنۈمى كۆرۈنەرلىك.","bu xil yumilaq marjan shekillik ion almashturghuchining ünümi körünerlik."]],"土崩瓦解":[["帝国最终土崩瓦解。","ئىمپېرىيە ئاخىرىدا پۈتۈنلەي پارچىلىنىپ كەتتى.","impériye axirida pütünley parchilinip ketti."]],"土伦":[["土伦是法国的一座城市。","تۇلون فرانسىيەنىڭ بىر شەھىرى.","tulon fransiyening bir shehiri."]],"坋粒":[["坋粒用于农业改良。","توپا دانچىلىرى يېزا ئىگىلىكىنى ياخشىلاشتا ئىشلىتىلىدۇ.","topa danchiliri yéza igilikini yaxshilashta ishlitilidu."]],"地震学家":[["地震学家通过数据分析预测地震风险。","زىلزىلىشۇناسلار سانلىق مەلۇمات ئانالىزى ئارقىلىق زىلزىلە خەۋپىنى مۆلچەرلەيدۇ.","zilzilishunaslar sanliq melumat analizi arqiliq zilzile xewpini mölcherleydu."]],"坡头区":[["坡头区是广州市的一个行政区。","پوتو رايونى گۇاڭجۇ شەھىرىنىڭ بىر مەمۇرىي رايونى.","poto rayoni guangju shehirining bir memuriy rayoni."]],"坚壁":[["敌人修筑了坚壁以抵御攻击。","دۈشمەن ھۇجۇمغا تاقابىل تۇرۇش ئۈچۈن جىيەنبى قۇردى.","düshmen hujumgha taqabil turush üchün jiyenbi qurdi."]],"坚定性":[["这种坚定性值得称赞。","بۇ خىل جىيەندىڭلىق ماختىشقا ئەرزىيدۇ.","bu xil jiyendingliq maxtishqa erziydu."]],"堡寨":[["这个堡寨历史悠久，值得一游。","بۇ قورغان ئۇزۇن تارىخقا ئىگە بولۇپ، زىيارەت قىلىشقا ئەرزىيدۇ.","bu qorghan uzun tarixqa ige bolup, ziyaret qilishqa erziydu."]],"壮硕":[["他体格壮硕，肌肉线条分明。","ئۇنىڭ بەدەنى پۇختا، مۇسكۇللىرى ئېنىق كۆرۈنىدۇ.","uning bedeni puxta, muskulliri éniq körünidu."]],"多汁":[["这个橙子非常多汁。","بۇ ئاپېلسىن ئىنتايىن شىرەلىك.","bu apélsin intayin shirelik."]],"梦寐以求":[["这真是我梦寐以求的机会。","بۇ ھەقىقەتەن مېنىڭ چۈشۈمدىكى پۇرسەت.","bu heqiqeten méning chüshümdiki purset."]],"大堡礁":[["大堡礁是澳大利亚著名的旅游景点。","چوڭ مارجان قىيىقى ئاۋسترالىيەنىڭ مەشھۇر ساياھەت مەنزىرىسى.","chong marjan qiyiqi awstraliyening meshhur sayahet menzirisi."]],"多态":[["这个程序具有多态性。","بۇ پروگرامما كۆپ شەكىللىك خۇسۇسىيەتكە ئىگە.","bu programma köp shekillik xususiyetke ige."]],"大寮":[["大寮是台湾的一个地名。","تالاۋ تەيۋەننىڭ بىر يەر نامى.","talaw teywenning bir yer nami."]],"大修":[["这次大修让旧车焕然一新。","بۇ قېتىملىق چوڭ رېمونت كونا ماشىنىنى پۈتۈنلەي يېڭىلاپ بەردى.","bu qétimliq chong rémont kona mashinini pütünley yéngilap berdi."]],"大义灭亲":[["为了大义，他不得不大义灭亲。","چوڭ ئادالەت ئۈچۈن ئۇ چوڭ ئادالەت بىلەن ئۇرۇق-تۇغقانلىرىدىن ۋاز كېچىشكە مەجبۇر بولدى.","chong adalet üchün u chong adalet bilen uruq-tughqanliridin waz kéchishke mejbur boldi."]],"大政方针":[["国家有大政方针。","دۆلەتنىڭ چوڭ سىياسەت ۋە پىرىنسىپلىرى بار.","döletning chong siyaset we pirinsipliri bar."]],"大声疾呼":[["他大声疾呼，要求改善环境。","ئۇ مۇھىتنى ياخشىلاشنى تەلەپ قىلىپ، يۇقىرى ئاۋازدا نىدا قىلدى.","u muhitni yaxshilashni telep qilip, yuqiri awazda nida qildi."]],"大阮":[["大阮是越南的一个王朝。","داڭۇي ۋىيېتنامنىڭ بىر سۇلالىسى.","danguy wiyétnamning bir sulalisi."]],"大头贴":[["商店里卖着各种大头贴。","دۇكاندا تۈرلۈك چوڭ باش سۈرەت يېپىشتۇرغۇچلىرى سېتىلىدۇ.","dukanda türlük chong bash süret yépishturghuchliri sétilidu."]],"天不怕地不怕":[["他天不怕地不怕，面对困难从不退缩。","ئۇ ئاسماندىنمۇ، يەردىنمۇ قورقمايدۇ، قىيىنچىلىققا دۇچ كەلگەندە ھەرگىز چېكىنمەيدۇ.","u asmandinmu, yerdinmu qorqmaydu, qiyinchiliqqa duch kelgende hergiz chékinmeydu."]],"天数":[["他的失败早已注定天数。","ئۇنىڭ مەغلۇبىيىتى ئاللىبۇرۇن تەقدىردە بېكىتىلگەن ئىدى.","uning meghlubiyiti alliburun teqdirde békitilgen idi."]],"大疮":[["医生帮他处理了腿上的大疮。","دوختۇر ئۇنىڭ پۇتىدىكى چوڭ يارىنى بىر تەرەپ قىلىشقا ياردەم قىلدى.","doxtur uning putidiki chong yarini bir terep qilishqa yardem qildi."]],"天地玄黄":[["天地玄黄，宇宙洪荒，这是古老的诗句。","ئاسمان-زېمىن قارا-سېرىق، ئالەم-كائىنات چەكسىز، بۇ قەدىمكى شېئىر جۈملىسىدۇر.","asman-zémin qara-sériq, alem-kainat cheksiz, bu qedimki shéir jümlisidur."]],"太上皇":[["太上皇是退位的皇帝。","تەي شاڭ خۇاڭ تەختتىن چەككەن ئىمپېراتوردۇر.","tey shang xuang texttin chekken impératordur."]],"天生的一对":[["他们是天生的一对。","ئۇلار تۇغۇلۇشتىن جۈپ بولغانلار.","ular tughulushtin jüp bolghanlar."]],"太监":[["古代宫廷中的太监负责侍奉皇帝。","قەدىمكى سارايدىكى تەيجيەنلەر ئىمپېراتورغا خىزمەت قىلىشقا مەسئۇل ئىدى.","qedimki saraydiki teyjyenler impératorgha xizmet qilishqa mes'ul idi."]],"夫妻店":[["夫妻店生意很红火。","ئەر-خوتۇن دۇكىنىنىڭ سودىسى بەك قىزىق.","er-xotun dukinining sodisi bek qiziq."]],"天炉座":[["天炉座位于南半球。","تيەنلۇجو جەنۇبىي يېرىم شاردا جايلاشقان.","tyenlujo jenubiy yérim sharda jaylashqan."]],"失常":[["他情绪失常，行为异常。","ئۇنىڭ كەيپىياتى نورمالسىز، ھەرىكىتى غەلىتە.","uning keypiyati normalsiz, herikiti ghelite."]],"天台":[["天台是佛教的重要道场。","تيەنتەي بۇددا دىنىنىڭ مۇھىم ئىبادەتگاھىدۇر.","tyentey budda dinining muhim ibadetgahidur."]],"奈良":[["奈良是日本的历史名城。","نارا ياپونىيەنىڭ تارىخىي شەھىرىدۇر.","nara yaponiyening tarixiy shehiridur."]],"大体解剖学":[["大体解剖学是医学的基础课程。","ئومۇمىي ئاناتومىيە تىببىي ئوقۇتۇشنىڭ ئاساسىي دەرسى.","omumiy anatomiye tibbiy oqutushning asasiy dersi."]],"大凤头燕鸥":[["大凤头燕鸥的羽毛非常鲜艳。","چوڭ فېڭتۇ يۇتقۇچى قۇشنىڭ پەيلىرى ناھايىتى پارقىراق.","chong féngtu yutquchi qushning peyliri nahayiti parqiraq."]],"大白话":[["他用大白话解释了这个复杂的概念。","ئۇ بۇ مۇرەككەپ ئۇقۇمنى ئاددىي تىل بىلەن چۈشەندۈردى.","u bu murekkep uqumni addiy til bilen chüshendürdi."]],"奏帖":[["奏帖是古代臣子向皇帝上书的方式。","مەمۇرىيەت ئەرزى قەدىمدە ۋەزىرلەرنىڭ ئىمپېراتورغا خەت سۇنۇش ئۇسۇلى ئىدى.","memuriyet erzi qedimde wezirlerning impératorgha xet sunush usuli idi."]],"奔泻":[["瀑布奔泻而下。","شەلەلې ئېقىپ چۈشۈۋاتىدۇ.","shelelé éqip chüshüwatidu."]],"夹生饭":[["夹生饭很难吃。","چالا پىشقان گۈرۈچنى يېيىش بەك تەس.","chala pishqan gürüchni yéyish bek tes."]],"套期保值":[["公司通过套期保值规避风险。","شىركەت يۈرۈم قىممەت ساقلاش ئارقىلىق خەتەردىن ساقلىنىدۇ.","shirket yürüm qimmet saqlash arqiliq xeterdin saqlinidu."]],"奥尔德尼岛":[["奥尔德尼岛是英国海外领土。","ئالدېرنىي ئارىلى بىرلەشمە پادىشاھلىقنىڭ چەت ئەل زېمىنى.","aldérniy arili birleshme padishahliqning chet el zémini."]],"妖孽":[["他行为如妖孽般诡异。","ئۇنىڭ ھەرىكىتى شەيتانلارچە غەلىتە.","uning herikiti sheytanlarche ghelite."]],"威利斯":[["威利斯发明了汽车。","ۋىللىس ماشىنىنى كەشىپ قىلغان.","willis mashinini keship qilghan."]],"威烈":[["他的威烈令人敬佩。","ئۇنىڭ ھەيۋەتلىك جاسارىتى كىشىنى ھۆرمەتكە سالىدۇ.","uning heywetlik jasariti kishini hörmetke salidu."]],"委任":[["他被正式委任为组长。","ئۇ رەسمىي ھالدا گۇرۇپپا باشلىقى قىلىپ تەيىنلەندى.","u resmiy halda guruppa bashliqi qilip teyinlendi."]],"孤儿院":[["孤儿院为孩子们提供了温暖的家。","يېتىملەر ئۆيى بالىلارغا ئىللىق ئۆي تەمىنلەيدۇ.","yétimler öyi balilargha illiq öy teminleydu."]],"嫠妇":[["她成为孤苦无依的嫠妇。","ئۇ يالغۇز ۋە پەرۋانىسىز تۇل خوتۇنغا ئايلاندى.","u yalghuz we perwanisiz tul xotungha aylandi."]],"安乐":[["追求安乐是人的天性。","خۇشال-خۇرام ياشاش ئىنساننىڭ تەبىئىي خاراكتېرى.","xushal-xuram yashash insanning tebiiy xaraktéri."]],"安源":[["安源是著名的革命老区。","ئەنيۈەن مەشھۇر ئىنقىلابىي كونا رايون.","enyüen meshhur inqilabiy kona rayon."]],"孤陋":[["他的知识孤陋，缺乏广博。","ئۇنىڭ بىلىمى تار، كەڭ مەلۇماتتىن كەم.","uning bilimi tar, keng melumattin kem."]],"安仁县":[["安仁县以丰富的文化遗产著称。","ئانرېن ناھىيىسى مول مەدەنىيەت مىراسلىرى بىلەن تونۇلغان.","anrén nahiyisi mol medeniyet mirasliri bilen tonulghan."]],"安家落户":[["移民需要先在当地安家落户。","كۆچمەنلەر ئالدى بىلەن يەرلىك جايدا ئۆي تىكلەپ ئورۇنلىشىشى كېرەك.","köchmenler aldi bilen yerlik jayda öy tiklep orunlishishi kérek."]],"宋任穷":[["宋任穷是中国革命家。","سۇڭ رېنچيۇڭ جۇڭگو ئىنقىلابچىسى.","sung rénchyung junggo inqilabchisi."]],"客诉":[["客服部门及时处理了用户的客诉。","مۇشتەرى مۇلازىمەت بۆلۈمى ئىشلەتكۈچىلەرنىڭ شىكايىتىنى ۋاقتىدا بىر تەرەپ قىلدى.","mushteri mulazimet bölümi ishletküchilerning shikayitini waqtida bir terep qildi."]],"宿分":[["这是宿分所致。","بۇ تەقدىرنىڭ ئىشى.","bu teqdirning ishi."]],"宿将":[["这位宿将曾是军队的统帅。","بۇ كونا سەركەردە ئارمىيەنىڭ باش قوماندانى بولغان.","bu kona serkerde armiyening bash qomandani bolghan."]],"家丑不可外传":[["家丑不可外传，要保密。","ئائىلە ئېيىبىنى سىرتقا تارقاتقىلى بولمايدۇ، سىر ساقلىش كېرەك.","aile éyibini sirtqa tarqatqili bolmaydu, sir saqlish kérek."]],"室友":[["室友之间要互相尊重。","ئۆي ھەمراھلىرى ئۆزئارا ھۆرمەت قىلىشى كېرەك.","öy hemrahliri öz'ara hörmet qilishi kérek."]],"密闭":[["房间必须保持密闭状态。","ئۆي چوقۇم تاقىق ھالەتتە ساقلىنىشى كېرەك.","öy choqum taqiq halette saqlinishi kérek."]],"富足":[["这个村庄生活富足，人人安居乐业。","بۇ كەنتنىڭ تۇرمۇشى باي، ھەممە ئادەم ئامان-ئېسەن تۇرمۇش كەچۈرمەكتە.","bu kentning turmushi bay, hemme adem aman-ésen turmush kechürmekte."]],"富阳":[["富阳历史悠久，文化底蕴深厚。","فۇياڭنىڭ تارىخى ئۇزۇن، مەدەنىيەت ئاساسى چوڭقۇر.","fuyangning tarixi uzun, medeniyet asasi chongqur."]],"寝室":[["我们的寝室很干净。","بىزنىڭ ياتاقخانىمىز ئىنتايىن پاكىز.","bizning yataqxanimiz intayin pakiz."]],"宁做鸡头，不做凤尾":[["他选择宁做鸡头，不做凤尾。","ئۇ توخۇنىڭ بېشى بولۇشنى تاللاپ، قۇشنىڭ قۇيرۇقى بولماسلىقنى تاللىدى.","u toxuning béshi bolushni tallap, qushning quyruqi bolmasliqni tallidi."]],"宁冈":[["宁冈的革命历史值得铭记。","نىڭگاڭنىڭ ئىنقىلابىي تارىخى ئەسلىشىگە ئەرزىيدۇ.","ninggangning inqilabiy tarixi eslishige erziydu."]],"富平":[["富平是陕西的一个历史名城。","فۇپىڭ شەنشىدىكى بىر تارىخىي شەھەر.","fuping shenshidiki bir tarixiy sheher."]],"尉犁县":[["尉犁县拥有独特的沙漠景观。","يۈلى ناھىيىسى ئۆزگىچە چۆل مەنزىرىسىگە ئىگە.","yüli nahiyisi özgiche chöl menzirisige ige."]],"射精管":[["射精管连接睾丸与尿道。","ئۇرۇق چىقىرىش نەيچىسى مەنىي بەزى بىلەن سۈيدۈك يولىنى تۇتاشتۇرىدۇ.","uruq chiqirish neychisi meniy bezi bilen süydük yolini tutashturidu."]],"将伯之助":[["将伯之助是成语，指朋友间的真诚帮助。","جياڭ بونىڭ ياردىمى دېگەن تىل ئىبارىسى دوستلار ئارىسىدىكى سەمىمىي ياردەمنى كۆرسىتىدۇ.","jyang boning yardimi dégen til ibarisi dostlar arisidiki semimiy yardemni körsitidu."]],"小隐隐于林，大隐隐于市":[["小隐隐于林，大隐隐于市。","كىچىك يوشۇرۇنلۇق ئورماندا، چوڭ يوشۇرۇنلۇق شەھەردە.","kichik yoshurunluq ormanda, chong yoshurunluq sheherde."]],"小书签":[["这个小书签是手工制作的。","بۇ كىچىك كىتاب بەلگىسى قولدا ياسالغان.","bu kichik kitab belgisi qolda yasalghan."]],"小黄瓜":[["小黄瓜口感清脆爽口。","كىچىك تەرخەمەك ئېغىزدا غىچىرلاپ يېيىلىدۇ.","kichik terxemek éghizda ghichirlap yéyilidu."]],"小黄脚鹬":[["小黄脚鹬在浅滩上觅食。","كىچىك سېرىق پۇتلىق سۇ قۇشى سايلىق جايدا يەم ئىزدەيدۇ.","kichik sériq putliq su qushi sayliq jayda yem izdeydu."]],"尿盆":[["他用尿盆接尿很方便。","ئۇ سۈيدۈك چىلتىسى بىلەن سۈيدۈك قىلىشى ئىنتايىن قولايلىق.","u süydük chiltisi bilen süydük qilishi intayin qolayliq."]],"展柜":[["博物馆的展柜里放着文物。","مۇزېينىڭ كۆرگەزمە ئىشكاپىدا يادىكارلىقلار قويۇلغان.","muzéyning körgezme ishkapida yadikarliqlar qoyulghan."]],"山奈钾":[["山奈钾是一种含有钾元素的化合物。","شەننەيجيا كالىي ئېلېمېنتىنى ئۆز ئىچىگە ئالغان بىر خىل بىرىكمە.","shenneyjya kaliy éléméntini öz ichige alghan bir xil birikme."]],"局级":[["局级官员负责区域管理。","جىڭ دەرىجىلىك ئەمەلدارلار رايون باشقۇرۇشقا مەسئۇل.","jing derijilik emeldarlar rayon bashqurushqa mes'ul."]],"冈仁波齐":[["冈仁波齐是佛教的重要圣地。","كايلاش تېغى بۇددا دىنىنىڭ مۇھىم مۇقەددەس جايى.","kaylash téghi budda dinining muhim muqeddes jayi."]],"崇明":[["崇明以生态闻名。","چۇڭمىڭ ئېكولوگىيە بىلەن داڭلىق.","chungming ékologiye bilen dangliq."]],"崭晴":[["天气终于崭晴，阳光普照。","ھاۋا ئاخىرى ئېچىلدى، قۇياش نۇرى ھەممە يەرنى يورۇتتى.","hawa axiri échildi, quyash nuri hemme yerni yorutti."]],"巴望":[["他巴望能中奖。","ئۇ مۇكاپاتقا ئېرىشىشنى ئۈمىد قىلىدۇ.","u mukapatqa érishishni ümid qilidu."]],"巴林右旗":[["巴林右旗以畜牧业闻名。","بەھرەين ئوڭ بېيقى چارۋىچىلىق بىلەن داڭلىق.","behreyn ong béyqi charwichiliq bilen dangliq."]],"巴氏杀菌":[["牛奶经过巴氏杀菌后更安全。","سۈت باستېر ئۇسۇلىدا بىر تەرەپ قىلىنغاندىن كېيىن تېخىمۇ بىخەتەر بولىدۇ.","süt bastér usulida bir terep qilinghandin kéyin téximu bixeter bolidu."]],"布囊":[["这个布囊可以装下日常用品。","بۇ خالتا كۈندىلىك ئىشلىتىلىدىغان بۇيۇملارنى سىغدۇرالايدۇ.","bu xalta kündilik ishlitilidighan buyumlarni sighduralaydu."]],"布袋戏":[["布袋戏是一种传统的表演艺术。","بۇز خالتا ئويۇنى ئەنئەنىۋى بىر ئىپادىلەش سەنئىتىدۇر.","buz xalta oyuni en'eniwi bir ipadilesh sen'itidur."]],"帕斯卡":[["帕斯卡是一位著名的数学家。","پاسكال داڭلىق بىر ماتېماتىكتۇر.","paskal dangliq bir matématiktur."]],"布隆迪":[["布隆迪是东非的一个小国。","بۇرۇندى شەرقىي ئافرىقىدىكى بىر كىچىك دۆلەتتۇر.","burundi sherqiy afriqidiki bir kichik dölettur."]],"巴力":[["巴力是古代神话中的一个神。","بائال قەدىمكى ئەپسانىلەردىكى بىر تەڭرى.","baal qedimki epsanilerdiki bir tengri."]],"帐号":[["请确认你的帐号是否正确。","ھېساباتىڭىزنىڭ توغرا ياكى ئەمەسلىكىنى جەزملەشتۈرۈڭ.","hésabatingizning toghra yaki emeslikini jezmleshtürüng."]],"带种":[["这种植物带种繁殖。","بۇ ئۆسۈملۈك ئۇرۇق بىلەن كۆپىيىدۇ.","bu ösümlük uruq bilen köpiyidu."]],"幕府":[["幕府是古代将军的军事机构。","مۇفۇ قەدىمكى زاماندىكى گېنېراللارنىڭ ھەربىي ئورگىنى.","mufu qedimki zamandiki générallarning herbiy orgini."]],"帝王切开":[["帝王切开是一种外科手术方法。","دىۋاڭ كېچەش ئۇسۇلى بىر خىل تاشقى كېسەللىك ئوپېراتسىيە ئۇسۇلىدۇر.","diwang kéchesh usuli bir xil tashqi késellik opératsiye usulidur."]],"幸运儿":[["他是这次抽奖的幸运儿。","ئۇ بۇ قۇرئە تارتىش پائالىيىتىنىڭ بەختلىك كىشىسى.","u bu qur'e tartish paaliyitining bextlik kishisi."]],"幽闭恐惧":[["他患有严重的幽闭恐惧。","ئۇ ئېغىر دەرىجىدىكى يېپىق جايدىن قورقۇش كېسىلىگە گىرىپتار بولغان.","u éghir derijidiki yépiq jaydin qorqush késilige giriptar bolghan."]],"几率":[["中奖的几率非常低。","ئۇتۇپ قېلىش ئېھتىماللىقى ئىنتايىن تۆۋەن.","utup qélish éhtimalliqi intayin töwen."]],"康巴地区":[["康巴地区以藏族文化著称。","كانڭبا رايونى تىبەت مەدەنىيىتى بىلەن داڭلىق.","kanngba rayoni tibet medeniyiti bilen dangliq."]],"平顺":[["平顺县拥有丰富的历史文化资源。","پىڭشۈن ناھىيىسى مول تارىخىي-مەدەنىيەت بايلىقلىرىغا ئىگە.","pingshün nahiyisi mol tarixiy-medeniyet bayliqlirigha ige."]],"广德县":[["广德县位于安徽省南部。","گۇاڭدې ناھىيىسى ئەنخۇي ئۆلكىسىنىڭ جەنۇبىي قىسمىدا جايلاشقان.","guangdé nahiyisi enxuy ölkisining jenubiy qismida jaylashqan."]],"弗州":[["弗州是弗吉尼亚州的简称。","ۋىرگىنىيە شىتاتى ۋىرگىنىيە شىتاتىنىڭ قىسقارتىلمىسى.","wirginiye shitati wirginiye shitatining qisqartilmisi."]],"张震":[["张震是一位台湾演员。","جياڭ جېن تەيۋەنلىك ئارتىس.","jyang jén teywenlik artis."]],"张皇":[["他听到消息后显得十分张皇。","ئۇ خەۋەرنى ئاڭلىغاندىن كېيىن ئىنتايىن ئىزدىرىپ كەتتى.","u xewerni anglighandin kéyin intayin izdirip ketti."]],"弹拨乐器":[["古筝是一种弹拨乐器。","گۇجېڭ بىر خىل تارلىما سازدۇر.","gujéng bir xil tarlima sazdur."]],"形容辞":[["形容辞是表达特征的词语。","سۈپەتلىك سۆزلەر ئالاھىدىلىكنى ئىپادىلەيدىغان سۆزلەردۇر.","süpetlik sözler alahidilikni ipadileydighan sözlerdur."]],"役使动物":[["役使动物需要遵循伦理规范。","ھايۋانلارنى ئەمگەككە سەل قىلدۇرۇشتا ئەخلاقىي ئۆلچەمگە رىئايە قىلىش كېرەك.","haywanlarni emgekke sel qildurushta exlaqiy ölchemge riaye qilish kérek."]],"形态学":[["形态学是研究生物形态的学科。","شەكىلشۇناسلىق جانلىقلارنىڭ شەكىلىنى تەتقىق قىلىدىغان پەندۇر.","shekilshunasliq janliqlarning shekilini tetqiq qilidighan pendur."]],"彩印":[["这张照片采用了彩印技术。","بۇ سۈرەت رەڭدار بېسىش تېخنىكىسىنى قوللانغان.","bu süret rengdar bésish téxnikisini qollanghan."]],"后段":[["后段剧情更加扣人心弦。","ئاخىرقى بۆلەك سىۇجېت تېخىمۇ كىشىنى مەھلىيا قىلىدۇ.","axirqi bölek siujét téximu kishini mehliya qilidu."]],"从心所欲":[["他退休后终于可以从心所欲了。","ئۇ پېنسىيەگە چىققاندىن كېيىن ئاخىرى كۆڭلى تارتقاننى قىلالايدۇ.","u pénsiyege chiqqandin kéyin axiri köngli tartqanni qilalaydu."]],"御厨":[["御厨为皇帝烹饪美食。","ئىمپېراتورلۇق ئاشپىزى پادىشاھ ئۈچۈن تائام تەييارلايدۇ.","impératorluq ashpizi padishah üchün taam teyyarlaydu."]],"德国汉莎航空公司":[["德国汉莎航空公司是欧洲巨头。","گېرمانىيە لۇفتھانزا ھاۋا يوللىرى شىركىتى ياۋروپانىڭ زور كارخانىسىدۇر.","gérmaniye lufthanza hawa yolliri shirkiti yawropaning zor karxanisidur."]],"心惊":[["这个消息让他心惊不已。","بۇ خەۋەر ئۇنىڭ يۈرىكىنى شىددەت بىلەن چۆچۈتتى.","bu xewer uning yürikini shiddet bilen chöchütti."]],"忠勇":[["他忠勇无畏，令人敬佩。","ئۇ سادىق ۋە قورقماس، كىشىلەرنى ھەيران قالدۇرىدۇ.","u sadiq we qorqmas, kishilerni heyran qalduridu."]],"忠君爱国":[["古人强调忠君爱国。","قەدىمكىلەر پادىشاھقا سادىق بولۇش ۋە ۋەتەننى سۆيۈشنى تەكىتلىگەن.","qedimkiler padishahqa sadiq bolush we wetenni söyüshni tekitligen."]],"恐慌发作":[["他突然出现了恐慌发作。","ئۇنىڭدا تۇيۇقسىز ۋەھىمە قوزغىلىش كۆرۈلدى.","uningda tuyuqsiz wehime qozghilish körüldi."]],"恁么":[["你为何要恁么对待我？","سەن نېمە ئۈچۈن ماڭا مۇشۇنداق مۇئامىلە قىلىسەن؟","sen néme üchün manga mushundaq muamile qilisen?"]],"恨意":[["他的恨意难以平息。","ئۇنىڭ ئۆچمەنلىكىنى بېسىشتۇرغىلى بولمايدۇ.","uning öchmenlikini bésishturghili bolmaydu."]],"恨透":[["我恨透这种虚伪。","مەن بۇنداق ساختىپەزلىكتىن قاتتىق ئۆچ ئالىمەن.","men bundaq saxtipezliktin qattiq öch alimen."]],"恭维":[["他经常恭维上司，以求升迁。","ئۇ دائىم رەھبىرىنى ماختاپ، ئەمەل ئۆسۈش ئۈمىد قىلىدۇ.","u daim rehbirini maxtap, emel ösüsh ümid qilidu."]],"急转":[["事情突然急转，让人措手不及。","ئىش تۇيۇقسىز ئۆزگىرىپ، كىشىنى تەييارلىقسىز قالدۇردى.","ish tuyuqsiz özgirip, kishini teyyarliqsiz qaldurdi."]],"耻骂":[["她耻骂无礼之人。","ئۇ ئەدەپسىز كىشىلەرنى ئۇياتلىق سۆز بىلەن تىللىدى.","u edepsiz kishilerni uyatliq söz bilen tillidi."]],"愚见":[["这只是我的愚见。","بۇ پەقەت مېنىڭ نادان پىكىرىم.","bu peqet méning nadan pikirim."]],"愚鲁":[["他愚鲁不堪，无法沟通。","ئۇ بەك ئەخمىق، ئالاقە قىلغىلى بولمايدۇ.","u bek exmiq, alaqe qilghili bolmaydu."]],"爱滋病毒":[["爱滋病毒会破坏免疫系统。","ئىممۇنىتېت كەمچىلىكى ۋىرۇسى ئىممۇنىتېت سىستېمىسىنى بۇزىدۇ.","immunitét kemchiliki wirusi immunitét sistémisini buzidu."]],"想出":[["她终于想出了一个好办法。","ئۇ ئاخىرى بىر ياخشى ئامالنى تېپىپ چىقتى.","u axiri bir yaxshi amalni tépip chiqti."]],"懵逼":[["他看到结果后懵逼了。","ئۇ نەتىجىنى كۆرگەندىن كېيىن ئەس-ھوشىدىن ئاداشتى.","u netijini körgendin kéyin es-hoshidin adashti."]],"怀旧":[["他听老歌时总是感到怀旧。","ئۇ كونا ناخشىلارنى ئاڭلىغاندا ھەمىشە ئەسكىچە ئەسلىمىلەرگە چۆمىدۇ.","u kona naxshilarni anglighanda hemishe eskiche eslimilerge chömidu."]],"悬浮物":[["水中的悬浮物会影响水体的清澈度。","سۇدىكى لەۋلەپ تۇرغان ماددىلار سۇ جىسىمىنىڭ سۈزۈكلۈكىگە تەسىر كۆرسىتىدۇ.","sudiki lewlep turghan maddilar su jisimining süzüklükige tesir körsitidu."]],"戴安娜":[["戴安娜是英国王妃。","دىئانا ئەنگىلىيە پادىشاھ ئايالى ئىدى.","diana engiliye padishah ayali idi."]],"戴帽子":[["他戴帽子时总是歪歪的。","ئۇ دوپپا كىيگەندە ھەمىشە قىڭغىر كىيىدۇ.","u doppa kiygende hemishe qingghir kiyidu."]],"手抓羊肉":[["手抓羊肉是蒙古的特色菜。","قولدا تۇتۇپ يېيىلىدىغان قوي گۆشى موڭغۇلنىڭ ئالاھىدە تائامى.","qolda tutup yéyilidighan qoy göshi mongghulning alahide taami."]],"打滚":[["他躺在地上打滚，假装受伤。","ئۇ يەردە يېتىپ دومىلاپ، يارىلانغاندەك قىلدى.","u yerde yétip domilap, yarilanghandek qildi."]],"手排":[["手排挡的车型操作起来更顺手。","قول بىلەن ئالماشتۇرىدىغان ماشىنا تىپىنى باشقۇرۇش تېخىمۇ قولايلىق.","qol bilen almashturidighan mashina tipini bashqurush téximu qolayliq."]],"才气":[["他的才气感染了整个团队。","ئۇنىڭ تالانتى پۈتۈن گۇرۇپپىغا تەسىر كۆرسەتتى.","uning talanti pütün guruppigha tesir körsetti."]],"扇风":[["他用手扇风降温。","ئۇ قولى بىلەن يەلپۈپ تېمپېراتۇرىنى تۆۋەنلەتتى.","u qoli bilen yelpüp témpératurini töwenletti."]],"托儿":[["托儿所照顾孩子。","بوۋاقلار باغچىسى بالىلارغا قارايدۇ.","bowaqlar baghchisi balilargha qaraydu."]],"扳不倒儿":[["这个扳不倒儿设计得很巧妙。","بۇ قۇلاقلىق ئويۇنچۇقنىڭ لايىھەسى ئىنتايىن چىرايلىق قىلىنغان.","bu qulaqliq oyunchuqning layihesi intayin chirayliq qilinghan."]],"扳机":[["扣动扳机，枪声响起。","تەڭگىنى تارتىپ، ئوق ئاۋازى ياڭرىدى.","tenggini tartip, oq awazi yangridi."]],"成人向":[["这部电影是成人向的，内容较为深刻。","بۇ كىنو چوڭلارغا قارىتىلغان بولۇپ، مەزمۇنى بىر قەدەر چوڭقۇر.","bu kino chonglargha qaritilghan bolup, mezmuni bir qeder chongqur."]],"折寿":[["过度劳累可能会折寿。","ھەددىدىن زىيادە ھارغىنلىق ئۆمرنى قىسقارتىشى مۇمكىن.","heddidin ziyade harghinliq ömrni qisqartishi mumkin."]],"找补":[["他试图找补，但效果不佳。","ئۇ تولۇقلاشقا تىرىشتى، ئەمما ئۈنۈمى ياخشى بولمىدى.","u toluqlashqa tirishti, emma ünümi yaxshi bolmidi."]],"拍演":[["演员在拍演戏剧。","ئارتىس تىياتىر ئوينىماقتا.","artis tiyatir oynimaqta."]],"抖落":[["他轻轻抖落衣服上的灰尘。","ئۇ كىيىمىدىكى چاڭ-توزاننى ئاستا قاقتى.","u kiyimidiki chang-tozanni asta qaqti."]],"拘拿":[["警察迅速拘拿罪犯。","ساقچىلار جىنايەتچىنى تېزلا تۇتتى.","saqchilar jinayetchini tézla tutti."]],"拙政园":[["拙政园是苏州的名园。","كەمتەرلىك باغچىسى سۇجۇنىڭ مەشھۇر باغچىسىدۇر.","kemterlik baghchisi sujuning meshhur baghchisidur."]],"招聘机构":[["这家招聘机构很专业。","بۇ خىزمەتچى قوبۇل قىلىش ئورگىنى ناھايىتى كەسپىي.","bu xizmetchi qobul qilish orgini nahayiti kespiy."]],"拼音文字":[["汉字属于表意文字，而非拼音文字。","خەنزۇ يېزىقى مەنىۋى يېزىق بولۇپ، پىنيىن يېزىقى ئەمەس.","xenzu yéziqi meniwi yéziq bolup, pinyin yéziqi emes."]],"持守":[["她持守初心，从未改变。","ئۇ ئەسلىي نىيىتىنى تۇتۇپ، ھەرگىز ئۆزگەرتمىدى.","u esliy niyitini tutup, hergiz özgertmidi."]],"拾级而上":[["沿着石阶拾级而上，景色越来越美。","تاش پەلەمپەي بويىچە چىققانسېرى مەنزىرە تېخىمۇ گۈزەللىشىۋاتىدۇ.","tash pelempey boyiche chiqqanséri menzire téximu güzellishiwatidu."]],"拾芥":[["他拾芥于细微之处，成就非凡事业。","ئۇ ئىنچىكە يەرلەردىن پايدىلىنىپ، ئادەتتىن تاشقىرى ئىشلارنى قىلدى.","u inchike yerlerdin paydilinip, adettin tashqiri ishlarni qildi."]],"指令名字":[["指令名字需明确具体。","كۆرسەتمە ئىسمى ئېنىق ۋە كونكرېت بولۇشى كېرەك.","körsetme ismi éniq we konkrét bolushi kérek."]],"扫盲":[["扫盲教育很重要。","ساۋاتسىزلىقنى يوقىتىش تەربىيىسى ئىنتايىن مۇھىم.","sawatsizliqni yoqitish terbiyisi intayin muhim."]],"扫雪车":[["扫雪车清理了道路。","قار تازىلاش ماشىنىسى يولنى تازىلىدى.","qar tazilash mashinisi yolni tazilidi."]],"排犹":[["排犹行为严重违背人道主义原则。","يەھۇدىيلارغا قارشى ھەرىكەت ئىنسانپەرۋەرلىك پرىنسىپىغا ئېغىر خىلاپلىق قىلىدۇ.","yehudiylargha qarshi heriket insanperwerlik prinsipigha éghir xilapliq qilidu."]],"排风口":[["排风口需要定期清洁。","شامال چىقىرىش ئېغىزىنى مۇنتىزىم تازىلاش كېرەك.","shamal chiqirish éghizini muntizim tazilash kérek."]],"探索性":[["这项研究具有探索性意义。","بۇ تەتقىقات ئىزدىنىش خاراكتېرلىك ئەھمىيەتكە ئىگە.","bu tetqiqat izdinish xaraktérlik ehmiyetke ige."]],"提价":[["公司决定对部分产品提价。","شىركەت بەزى مەھسۇلاتلارنىڭ باھاسىنى ئۆستۈرۈشنى قارار قىلدى.","shirket bezi mehsulatlarning bahasini östürüshni qarar qildi."]],"挟带":[["他挟带私心，影响了公正判决。","ئۇ شەخسىي مەنپەئەتنى تۇتقۇن قىلىپ، ئادىل ھۆكۈمگە تەسىر كۆرسەتتى.","u shexsiy menpeetni tutqun qilip, adil hökümge tesir körsetti."]],"援军":[["援军及时赶到，扭转了战局。","ياردەمچى قوشۇن ۋاقتىدا يېتىپ كېلىپ، جەڭ ئەھۋالىنى ئۆزگەرتىۋەتتى.","yardemchi qoshun waqtida yétip kélip, jeng ehwalini özgertiwetti."]],"挑高":[["他挑高声音，让所有人都听到。","ئۇ ئاۋازىنى ئېگىز كۆتۈرۈپ، ھەممەيلەنگە ئاڭلاتتى.","u awazini égiz kötürüp, hemmeylenge anglatti."]],"揭破":[["他揭破了谎言的真相。","ئۇ يالغاننىڭ ھەقىقىي يۈزىنى ئېچىپ تاشلىدى.","u yalghanning heqiqiy yüzini échip tashlidi."]],"提起":[["他提起沉重的箱子。","ئۇ ئېغىر يەشىكنى كۆتۈردى.","u éghir yeshikni kötürdi."]],"搬弄是非":[["别搬弄是非。","ئىغۋا تارقىتىپ ئادەملەرنىڭ ئارىسىنى بۇزماڭ.","ighwa tarqitip ademlerning arisini buzmang."]],"搭伴":[["他搭伴去旅行。","ئۇ ھەمراھ بىلەن سەپەرگە چىقتى.","u hemrah bilen seperge chiqti."]],"搭嘴":[["他搭嘴说了几句。","ئۇ ئاغزىنى ئېچىپ بىر نەچچە ئېغىز سۆزلەپ قويدى.","u aghzini échip bir nechche éghiz sözlep qoydi."]],"探身子":[["她探身子想看清远处的风景。","ئۇ يىراقتىكى مەنزىرىنى ئېنىق كۆرۈش ئۈچۈن بېشىنى سۇندى.","u yiraqtiki menzirini éniq körüsh üchün béshini sundi."]],"撤下":[["把海报从墙上撤下来。","چوڭ ئېلاننى تامدىن چۈشۈرۈڭ.","chong élanni tamdin chüshürüng."]],"抚远三角洲":[["抚远三角洲是重要的湿地生态区。","فۇيۈەن دېلتاسى مۇھىم سۇلۇق يەر ئېكولوگىيەلىك رايونى.","fuyüen déltasi muhim suluq yer ékologiyelik rayoni."]],"拨奏":[["琵琶的拨奏技巧十分独特。","پىپانىڭ چېكىش تېخنىكىسى ئىنتايىن ئۆزگىچە.","pipaning chékish téxnikisi intayin özgiche."]],"擦亮眼睛":[["擦亮眼睛，别被假象迷惑。","كۆزىڭىزنى ئېچىڭ، يالغان كۆرۈنۈشلەرگە ئالدىنىپ قالماڭ.","közingizni éching, yalghan körünüshlerge aldinip qalmang."]],"放不下心":[["她总是放不下心，担心孩子。","ئۇ ھەمىشە كۆڭلىنى بىخەتەر تۇتالماي، بالىسى ئۈچۈن ئەنسىرەيدۇ.","u hemishe könglini bixeter tutalmay, balisi üchün ensireydu."]],"放入":[["把调料放入锅中。","تەمبەھەرلەرنى قازانغا سېلىڭ.","tembeherlerni qazangha séling."]],"支架":[["相机支架能防止拍摄时抖动。","كامېرا تىرەگۈچى سۈرەتكە تارتىش جەريانىدىكى تەۋرىنىشنىڭ ئالدىنى ئالىدۇ.","kaméra tiregüchi süretke tartish jeryanidiki tewrinishning aldini alidu."]],"故而":[["故而，他选择放弃这次机会。","شۇڭا، ئۇ بۇ پۇرسەتتىن ۋاز كېچىشنى تاللىدى.","shunga, u bu pursettin waz kéchishni tallidi."]],"故里":[["这处故里承载着我的童年回忆。","بۇ كونا يۇرت مېنىڭ بالىلىق ئەسلىمەلىرىمنى ئۆز ئىچىگە ئالىدۇ.","bu kona yurt méning baliliq eslimelirimni öz ichige alidu."]],"摊薄后每股盈利":[["摊薄后每股盈利为2.5元。","سۇيۇلدۇرغاندىن كېيىن ھەر پەي پايدىسى 2.5 يۈەن بولدى.","suyuldurghandin kéyin her pey paydisi 2.5 yüen boldi."]],"摊钱":[["大家摊钱买了礼物。","ھەممەيلەن پۇل تەقسىملەپ سوۋغات سېتىۋالدى.","hemmeylen pul teqsimlep sowghat sétiwaldi."]],"搅和":[["把调料搅和均匀。","تەمبىلەرنى تەڭ ئارىلاشتۇرۇڭ.","tembilerni teng arilashturung."]],"敬贤礼士":[["他始终敬贤礼士，广受好评。","ئۇ ھەمىشە ئەقىل-پاراسەتلىكلەرنى ھۆرمەتلەپ، كەڭ خەلقنىڭ ماختىشىغا ئېرىشكەن.","u hemishe eqil-parasetliklerni hörmetlep, keng xelqning maxtishigha érishken."]],"数列":[["这个数列的规律非常清晰。","بۇ سانلار تىزىملىكىنىڭ قانۇنىيىتى ئىنتايىن ئېنىق.","bu sanlar tizimlikining qanuniyiti intayin éniq."]],"敷设":[["工人正在敷设地下管道。","ئىشچىلار يەر ئاستى تۇرۇبىسىنى ياتقۇزۇۋاتىدۇ.","ishchilar yer asti turubisini yatquzuwatidu."]],"敌害":[["敌害对农作物造成破坏。","دۈشمەن زىيانكەشلىرى يېزا ئىگىلىك زىرائەتلىرىگە بۇزغۇنچىلىق قىلدى.","düshmen ziyankeshliri yéza igilik ziraetlirige buzghunchiliq qildi."]],"文山会海":[["文山会海现象令人头疼。","يىغىن-ھۆججەت دېڭىزى ھادىسىسى كىشىنى باش ئاغرىتىدۇ.","yighin-höjjet déngizi hadisisi kishini bash aghritidu."]],"斑喉希鹛":[["这种斑喉希鹛的叫声十分悦耳。","بۇ خىل داغلىق تاماقچى قۇشنىڭ ئاۋازى ئىنتايىن يېقىملىق.","bu xil daghliq tamaqchi qushning awazi intayin yéqimliq."]],"斗南镇":[["斗南镇有许多传统的市集。","دونان بازىرىدا نۇرغۇن ئەنئەنىۋى بازارلار بار.","donan bazirida nurghun en'eniwi bazarlar bar."]],"新北":[["新北地区的交通网络十分发达便利。","يېڭىبېي رايونىنىڭ قاتناش تورى ئىنتايىن تەرەققىي قىلغان ۋە قۇلايلىق.","yéngibéy rayonining qatnash tori intayin tereqqiy qilghan we qulayliq."]],"新店":[["新店有许多历史悠久的建筑。","يېڭىدىيەندە تارىخى ئۇزۇن نۇرغۇن بىنالار بار.","yéngidiyende tarixi uzun nurghun binalar bar."]],"新嫁娘":[["新嫁娘的笑容格外灿烂。","يېڭى كېلىننىڭ كۈلۈمسىرىشى ئالاھىدە نۇرلۇق ئىدى.","yéngi kélinning külümsirishi alahide nurluq idi."]],"敛财":[["他敛财的手段十分卑劣。","ئۇنىڭ بايلىق جۇغلىش ۋاسىتىسى بەك رەزىل ئىدى.","uning bayliq jughlish wasitisi bek rezil idi."]],"新林":[["新林地区拥有丰富的自然资源。","شىنلىن رايونى باي تەبىئىي بايلىققا ئىگە.","shinlin rayoni bay tebiiy bayliqqa ige."]],"新荣区":[["新荣区是城市的核心商业区。","شىنرۇڭ رايونى شەھەرنىڭ يادرولۇق سودا رايونى.","shinrung rayoni sheherning yadroluq soda rayoni."]],"新罗":[["新罗王朝曾是朝鲜的强国。","شىلا دەۋرىدىكى خانلىق بىر ۋاقىتلاردا چاۋشيەننىڭ كۈچلۈك دۆلىتى ئىدى.","shila dewridiki xanliq bir waqitlarda chawshyenning küchlük döliti idi."]],"方向感":[["良好的方向感有助于快速定位目标。","ياخشى يۆنىلىش تۇيغۇسى نىشاننى تېز ئورۇنلاشتۇرۇشقا ياردەم بېرىدۇ.","yaxshi yönilish tuyghusi nishanni téz orunlashturushqa yardem béridu."]],"方山县":[["方山县位于山西省中部。","فاڭشەن ناھىيىسى شەنشى ئۆلكىسىنىڭ ئوتتۇرىسىدا جايلاشقان.","fangshen nahiyisi shenshi ölkisining otturisida jaylashqan."]],"施政报告":[["政府发布了施政报告。","ھۆكۈمەت سىياسەت دوكلاتىنى ئېلان قىلدى.","hökümet siyaset doklatini élan qildi."]],"既有":[["这家店既有美食，也有美景。","بۇ دۇكاندا ھەم تائاملىق تاماق، ھەم گۈزەل مەنزىرە بار.","bu dukanda hem taamliq tamaq, hem güzel menzire bar."]],"昂利":[["昂利的笑容很温暖。","ئاڭلىنىڭ كۈلۈمسىرىشى ئىنتايىن ئىللىق.","anglining külümsirishi intayin illiq."]],"早衰":[["早衰症会影响身体机能。","بالدۇر قېرىش كېسىلى بەدەن ئىقتىدارىغا تەسىر كۆرسىتىدۇ.","baldur qérish késili beden iqtidarigha tesir körsitidu."]],"旨意":[["请领会领导旨意。","رەھبەرنىڭ پەرمانىنى چۈشىنىڭ.","rehberning permanini chüshining."]],"明光市":[["明光市位于安徽省东南部。","مىڭگۇاڭ شەھىرى ئەنخۇي ئۆلكىسىنىڭ جەنۇبىي شەرقىي قىسمىدا جايلاشقان.","mingguang shehiri enxuy ölkisining jenubiy sherqiy qismida jaylashqan."]],"昌平":[["昌平的长城遗址壮观。","چاڭپىڭنىڭ سەددىچىن سېپىلى خارابىسى ھەيۋەتلىك.","changpingning seddichin sépili xarabisi heywetlik."]],"晏子春秋":[["《晏子春秋》是记载晏子言行的书。","«يەنزى چۇنچيۇ» يەنزىنىڭ سۆزلىرى ۋە قىلمىشلىرى خاتىرىلەنگەن كىتاب.","«yenzi chunchyu» yenzining sözliri we qilmishliri xatirilengen kitab."]],"晨昏":[["晨昏时分，天空格外美丽。","ئەتىگەن-كەچقۇرۇن ۋاقىتلىرىدا، ئاسمان ئالاھىدە گۈزەل.","etigen-kechqurun waqitlirida, asman alahide güzel."]],"普通䴓":[["这种普通䴓常见于森林中。","بۇ خىل ئادەتتىكى كۆك چىمچىق ئورمانلاردا كۆپ ئۇچرايدۇ.","bu xil adettiki kök chimchiq ormanlarda köp uchraydu."]],"暴敛":[["暴敛激起了民众的愤怒。","ئېغىر باج ئاممىنىڭ غەزىپىنى قوزغىدى.","éghir baj ammining ghezipini qozghidi."]],"书名":[["这本书的书名很有趣。","بۇ كىتابنىڭ نامى ئىنتايىن قىزىقارلىق.","bu kitabning nami intayin qiziqarliq."]],"会要":[["会议会要已整理完毕。","يىغىن خاتىرىسى تەييارلىنىپ بولدى.","yighin xatirisi teyyarlinip boldi."]],"会议展览":[["会议展览吸引了许多观众。","يىغىن كۆرگەزمىسى كۆپلىگەن تاماشىبىنلارنى جەلپ قىلدى.","yighin körgezmisi köpligen tamashibinlarni jelp qildi."]],"会宁":[["会宁是甘肃省的一个城市。","خۇينىڭ گەنسۇ ئۆلكىسىدىكى بىر شەھەر.","xuyning gensu ölkisidiki bir sheher."]],"最小化":[["点击按钮即可最小化窗口。","كۇنۇپكىنى چېكىش ئارقىلىق كۆزنەكنى ئەڭ كىچىكلىتىشكە بولىدۇ.","kunupkini chékish arqiliq köznekni eng kichiklitishke bolidu."]],"曼哈顿区":[["曼哈顿区是纽约市的中心地带。","مانخاتتان رايونى نيۇيورك شەھىرىنىڭ مەركىزىي رايونى.","manxattan rayoni nyuyork shehirining merkiziy rayoni."]],"书法家":[["这位书法家擅长行书和草书。","بۇ خەتتات يۈرۈش خەت ۋە چۆرۈك خەتتە ماھىردۇر.","bu xettat yürüsh xet we chörük xette mahirdur."]],"书牍":[["古代的书牍主要用于书信往来。","قەدىمكى كىتاب خەتلىرى ئاساسلىقى خەت-چەك ئالاقىسىگە ئىشلىتىلگەن.","qedimki kitab xetliri asasliqi xet-chek alaqisige ishlitilgen."]],"朋比为奸":[["他们朋比为奸，危害社会。","ئۇلار يامانلىقتا بىرلىشىپ، جەمئىيەتكە زىيان يەتكۈزىدۇ.","ular yamanliqta birliship, jem'iyetke ziyan yetküzidu."]],"服务提供商":[["他是主要的服务提供商。","ئۇ ئاساسلىق مۇلازىمەت تەمىنلىگۈچى.","u asasliq mulazimet teminligüchi."]],"朝鲜八道":[["朝鲜八道是古代朝鲜的重要行政区划。","چاۋشيەننىڭ سەككىز يولى قەدىمكى چاۋشيەننىڭ مۇھىم مەمۇرىي رايون تەقسىماتى ئىدى.","chawshyenning sekkiz yoli qedimki chawshyenning muhim memuriy rayon teqsimati idi."]],"有权威":[["这位教授在学术界很有权威。","بۇ پروفېسسور ئىلمىي جەھەتتە ناھايىتى نوپۇزلۇق.","bu proféssor ilmiy jehette nahayiti nopuzluq."]],"木乃伊化":[["木乃伊化需要极其复杂的工艺。","مومىيالىش ئىنتايىن مۇرەككەپ ھۈنەرنى تەلەپ قىلىدۇ.","momiyalish intayin murekkep hünerni telep qilidu."]],"木筏":[["木筏是渡河的简易工具。","ياغاچ سال دەريادىن ئۆتۈشنىڭ ئاددىي قورالى.","yaghach sal deryadin ötüshning addiy qorali."]],"李代桃僵":[["李代桃僵比喻代人受过。","لى دەيشۇ لىنىڭ ئورنىغا ئازاب چەكش دېگەن مەنىدە.","li deyshu lining ornigha azab cheksh dégen menide."]],"本体":[["本体是哲学中讨论的核心概念。","ئاساسىي جەۋھەر پەلسەپەدە مۇھاكىمە قىلىنىدىغان يادرولۇق ئۇقۇمدۇر.","asasiy jewher pelsepede muhakime qilinidighan yadroluq uqumdur."]],"李富春":[["李富春是一位开国领导人。","لى فۇچۈن دۆلەت قۇرۇش رەھبەرلىرىنىڭ بىرى.","li fuchün dölet qurush rehberlirining biri."]],"李逵":[["李逵是《水浒传》中的英雄人物。","لى كۈي «سۇ بويى تەزكىرىسى» دىكى قەھرىمان شەخس.","li küy «su boyi tezkirisi» diki qehriman shexs."]],"李陵":[["李陵的诗歌流传至今。","لى لىڭنىڭ شېئىرلىرى بۈگۈنگىچە داۋاملىشىپ كەلدى.","li lingning shéirliri bügüngiche dawamliship keldi."]],"杜鹃":[["杜鹃是一种美丽的鸣禽。","دۇجۈەن گۈزەل سايرا قۇشى.","dujüen güzel sayra qushi."]],"杜鹃花科":[["杜鹃花科植物大多色彩鲜艳。","دۇجۈەن گۈلى ئائىلىسى ئۆسۈملۈكلىرىنىڭ كۆپىنچىسى رەڭگى پارقىراق.","dujüen güli ailisi ösümlüklirining köpinchisi renggi parqiraq."]],"杳渺":[["杳渺形容遥远而模糊的状态。","ياۋمياۋ يىراق ۋە غۇۋا ھالەتنى تەسۋىرلەيدۇ.","yawmyaw yiraq we ghuwa haletni teswirleydu."]],"松山区":[["松山区是松山市的中心区。","سۇڭشەن رايونى سۇڭشەن شەھىرىنىڭ مەركىزىي رايونى.","sungshen rayoni sungshen shehirining merkiziy rayoni."]],"板门店停战村":[["板门店停战村历史悠久。","پانمۇندىن توختىتىش كەنتىنىڭ تارىخى ئۇزۇن.","panmundin toxtitish kentining tarixi uzun."]],"林吉特":[["林吉特是马来西亚的货币单位。","رىڭگىت مالايسىيانىڭ پۇل بىرلىكى.","ringgit malaysiyaning pul birliki."]],"林州":[["林州以独特的自然风光闻名全国。","لىنجو پۈتۈن مەملىكەتتە ئۆزگىچە تەبىئىي مەنزىرىسى بىلەن تونۇلغان.","linjo pütün memlikette özgiche tebiiy menzirisi bilen tonulghan."]],"杜氏腺":[["杜氏腺在细胞中起重要作用。","دۇشى بەزى ھۈجەيرىلەردە مۇھىم رول ئوينايدۇ.","dushi bezi hüjeyrilerde muhim rol oynaydu."]],"李诵":[["李诵是唐宪宗的年号。","لى سۇڭ تاڭ شيەنزۇڭنىڭ يىل نامى.","li sung tang shyenzungning yil nami."]],"杌凳":[["这个杌凳很小巧。","بۇ كىچىك ئورۇندۇق ناھايىتى كىچىك ۋە چىرايلىق.","bu kichik orunduq nahayiti kichik we chirayliq."]],"柯林斯":[["柯林斯是一位著名的作家。","كوللىنس داڭلىق بىر يازغۇچىدۇر.","kollins dangliq bir yazghuchidur."]],"柳莺":[["柳莺的歌声清脆悦耳，令人陶醉。","ليۇيىڭ قۇشىنىڭ ناخشىسى سۈزۈك ۋە يېقىملىق بولۇپ، كىشىنى مەست قىلىدۇ.","lyuying qushining naxshisi süzük we yéqimliq bolup, kishini mest qilidu."]],"枯叶":[["秋天一到，树上的枯叶纷纷飘落。","كۈز كەلگەندە، دەرەختىكى قۇرۇق ياپراقلار ئۇچۇپ چۈشىدۇ.","küz kelgende, derextiki quruq yapraqlar uchup chüshidu."]],"核磁共振":[["核磁共振用于医学影像诊断。","يادرو ماگنىت رېزونانسى تىببىي تەسۋىر دىئاگنوزىدا قوللىنىلىدۇ.","yadro magnit rézonansi tibbiy teswir diagnozida qollinilidu."]],"核技术":[["核技术推动了能源领域的进步。","يادرو تېخنىكىسى ئېنېرگىيە ساھەسىنىڭ تەرەققىياتىنى ئىلگىرى سۈردى.","yadro téxnikisi énérgiye sahesining tereqqiyatini ilgiri sürdi."]],"桃花水母":[["桃花水母是一种透明的生物。","شاپتۇل گۈلى سۇ ئانىسى شەپپەلدەك سۈزۈك جانلىق.","shaptul güli su anisi sheppeldek süzük janliq."]],"桃金娘科":[["桃金娘科包含许多植物种类。","تۇتۇم گۈللىقى ئائىلىسى نۇرغۇن ئۆسۈملۈك تۈرلىرىنى ئۆز ئىچىگە ئالىدۇ.","tutum gülliqi ailisi nurghun ösümlük türlirini öz ichige alidu."]],"梅花拳":[["梅花拳是一种武术。","مېيخۇاچۈەن بىر خىل ھەربىي سەنئەت.","méyxuachüen bir xil herbiy sen'et."]],"梗塞":[["梗塞是指血管被堵塞的医学状况。","گېڭسە قان تومۇرلارنىڭ تىقىلىپ قېلىشىنى كۆرسىتىدىغان تېببىي ھالەت.","géngse qan tomurlarning tiqilip qélishini körsitidighan tébbiy halet."]],"梵婀玲":[["梵婀玲指小提琴。","فەنزە سىكىپكا كىچىك ئىسكىرىپكىنى كۆرسىتىدۇ.","fenze sikipka kichik iskiripkini körsitidu."]],"棕三趾鹑":[["棕三趾鹑是濒危鸟类。","قوڭۇر ئۈچ بارماق بۆدۈنىسى خەتەر ئاستىدىكى قۇش.","qongur üch barmaq bödünisi xeter astidiki qush."]],"械斗":[["双方发生激烈械斗。","ئىككى تەرەپ ئوتتۇرىسىدا كەسكىن مېخانىكىلىق ئۇرۇش يۈز بەردى.","ikki terep otturisida keskin méxanikiliq urush yüz berdi."]],"椅背":[["椅背是椅子后方的支撑部分。","ئورۇندۇقنىڭ ئارقىسى ئورۇندۇقنىڭ كەينى تەرەپتىكى تىرەك قىسمى.","orunduqning arqisi orunduqning keyni tereptiki tirek qismi."]],"椪柑":[["椪柑是一种口感清甜的柑橘。","پېڭگان تاتلىق ۋە يېقىملىق تەملىك بىر خىل ئاپېلسىندۇر.","pénggan tatliq we yéqimliq temlik bir xil apélsindur."]],"椰林":[["椰林在微风中轻轻摇曳。","كوكونۇت ئورمانلىرى شامالدا ئاستا تەۋرىنىدۇ.","kokonut ormanliri shamalda asta tewrinidu."]],"楠梓区":[["楠梓区是台北市的一个行政区。","نەنزى رايونى تەيبېي شەھىرىنىڭ بىر مەمۇرىي رايونىدۇر.","nenzi rayoni teybéy shehirining bir memuriy rayonidur."]],"榆中":[["榆中是甘肃省的一个县。","يۈجۇڭ گەنسۇ ئۆلكىسىدىكى بىر ناھىيە.","yüjung gensu ölkisidiki bir nahiye."]],"桡骨":[["桡骨是前臂的重要骨骼。","رادىئۇس سۈڭىكى بىلەكنىڭ مۇھىم سۈڭىكى.","radius süngiki bilekning muhim süngiki."]],"桥本":[["桥本是一位著名作家。","چياۋبېن داڭلىق يازغۇچى.","chyawbén dangliq yazghuchi."]],"检控":[["检控方需提供充分证据支持指控。","ئەيىبلەش تەرەپ ئەيىبلەشنى قوللاش ئۈچۈن يېتەرلىك دەلىل تەمىنلىشى كېرەك.","eyiblesh terep eyibleshni qollash üchün yéterlik delil teminlishi kérek."]],"权利要求":[["合同中列明了所有权利要求。","توختامدا بارلىق ھوقۇق تەلەپلىرى تىزىپ كۆرسىتىلدى.","toxtamda barliq hoquq telepliri tizip körsitildi."]],"款步":[["他迈着款步走进房间。","ئۇ ئاستا قەدەملەر بىلەن ئۆيگە كىردى.","u asta qedemler bilen öyge kirdi."]],"歇艎":[["船在港口歇艎修整。","كېمە پورتقا توختاپ رېمونت قىلىندى.","kéme portqa toxtap rémont qilindi."]],"歌剧院":[["歌剧院的演出总是座无虚席。","ئوپېرا تىياتىرخانىسىنىڭ نومۇرلىرى ھەمىشە تولۇق.","opéra tiyatirxanisining nomurliri hemishe toluq."]],"正邪":[["正邪力量在较量。","ھەق بىلەن ناھەق كۈچلەر ئېغىرلىشىۋاتىدۇ.","heq bilen naheq küchler éghirlishiwatidu."]],"此消彼长":[["此消彼长，最终导致局势失控。","بىرى ئۆسۈپ يەنە بىرى چېكىنىپ، ئاخىرىدا ئەھۋال كونتروللۇقتىن چىقىپ كەتتى.","biri ösüp yene biri chékinip, axirida ehwal kontrolluqtin chiqip ketti."]],"正太":[["这个正太笑起来特别可爱。","بۇ شۇنداق تاتلىق كىچىك ئوغۇل كۈلگەندە ئىنتايىن يېقىملىق.","bu shundaq tatliq kichik oghul külgende intayin yéqimliq."]],"死刑缓期执行":[["他获得了死刑缓期执行。","ئۇ ئۆلۈم جازاسىنى كېچىكتۈرۈپ ئىجرا قىلىشقا ئېرىشتى.","u ölüm jazasini kéchiktürüp ijra qilishqa érishti."]],"死寂":[["房间里一片死寂，毫无声响。","ئۆيدە ئۆلۈم تىنچلىقى، ھېچقانداق ئاۋاز يوق.","öyde ölüm tinchliqi, héchqandaq awaz yoq."]],"死节":[["他坚守死节，宁死不屈。","ئۇ ئۆلگىچە سادىقلىقىنى ساقلاپ، ئۆلۈمگىمۇ باش ئەگمىدى.","u ölgiche sadiqliqini saqlap, ölümgimu bash egmidi."]],"归根":[["事情要归根到最初的原因。","ئىش ئەڭ ئاۋۋالقى سەۋەبىگە قايتىشى كېرەك.","ish eng awwalqi sewebige qaytishi kérek."]],"杀人不眨眼":[["这个歹徒杀人不眨眼。","بۇ رەزىل كىشى ئۆلتۈرۈشتە كۆزىنى چەكمەيدۇ.","bu rezil kishi öltürüshte közini chekmeydu."]],"杀人放火":[["他们杀人放火，无恶不作。","ئۇلار ئۆلتۈرۈش، ئوت قويۇش قاتارلىق ھەر قانداق يامانلىقنى قىلىدۇ.","ular öltürüsh, ot qoyush qatarliq her qandaq yamanliqni qilidu."]],"民族自决":[["民族自决权是国际法的核心。","مىللەتلەرنىڭ ئۆزىنى بەلگىلەش ھوقۇقى خەلقئارا قانۇننىڭ يادروسى.","milletlerning özini belgilesh hoquqi xelq'ara qanunning yadrosi."]],"段荃法":[["段荃法是一位杰出的工程师。","دۇەن چۈەنفا كۆزگە كۆرۈنگەن ئىنژېنېر ئىدى.","duen chüenfa közge körüngen inzhénér idi."]],"气死":[["他被这个消息气死了。","ئۇ بۇ خەۋەردىن غەزەپلىنىپ ئۆلدى.","u bu xewerdin ghezeplinip öldi."]],"毗连":[["两国领土毗连。","ئىككى دۆلەتنىڭ زېمىنى تۇتاش.","ikki döletning zémini tutash."]],"水能源":[["水能源对环境友好。","سۇ ئېنېرگىيىسى مۇھىتقا دوست.","su énérgiyisi muhitqa dost."]],"水军":[["网络水军故意散布虚假信息。","تور سۇ ئارمىيىسى قەستەن يالغان ئۇچۇر تارقىتىدۇ.","tor su armiyisi qesten yalghan uchur tarqitidu."]],"民变":[["民变迅速蔓延全国。","خەلق قوزغىلىڭى پۈتۈن مەملىكەتكە تېز تارقالدى.","xelq qozghilingi pütün memliketke téz tarqaldi."]],"氯纶":[["氯纶是一种合成纤维材料。","خلورلىق تالا بىر خىل سىنتېتىك تالا ماتېرىيالى.","xlorliq tala bir xil sintétik tala matériyali."]],"水力":[["水力是指水的流动所产生的力量。","سۇ كۈچى سۇنىڭ ئېقىشىدىن ھاسىل بولغان كۈچنى كۆرسىتىدۇ.","su küchi suning éqishidin hasil bolghan küchni körsitidu."]],"水横枝":[["这株植物的水横枝向四周伸展，形态优美。","بۇ ئۆسۈملۈكنىڭ سۇ توغرا شاخلىرى تەرەپ-تەرەپكە سوزۇلۇپ، شەكلى گۈزەل.","bu ösümlükning su toghra shaxliri terep-terepke sozulup, shekli güzel."]],"永生":[["人们追求永生是永恒的主题。","كىشىلەرنىڭ مەڭگۈلۈكنى ئىزدىشى مەڭگۈلۈك تېما.","kishilerning menggülükni izdishi menggülük téma."]],"江浦":[["江浦是南京历史悠久的老城区。","جياڭپۇ نەنجىڭنىڭ تارىخى ئۇزۇن كونا شەھەر رايونى.","jyangpu nenjingning tarixi uzun kona sheher rayoni."]],"汶川":[["汶川以地震灾害而闻名。","ۋېنچۈەن يەر تەۋرەش ئاپىتى بىلەن داڭلىق.","wénchüen yer tewresh apiti bilen dangliq."]],"气钻":[["气钻能快速钻穿坚硬的材质。","ھاۋا بۇرمىسى قاتتىق ماتېرىياللارنى تېز تېشىپ ئۆتەلەيدۇ.","hawa burmisi qattiq matériyallarni téz téship öteleydu."]],"气体离心":[["气体离心技术用于分离同位素。","گاز سېنترىفۇگا تېخنىكىسى ئىزوتوپلارنى ئايرىشقا ئىشلىتىلىدۇ.","gaz séntrifuga téxnikisi izotoplarni ayrishqa ishlitilidu."]],"气鸣乐器":[["这种气鸣乐器能发出悠扬的旋律。","بۇ خىل ھاۋا ساز ئەسۋابى ئېسىل مېلودىيە چىقارالايدۇ.","bu xil hawa saz eswabi ésil mélodiye chiqaralaydu."]],"沃伦·巴菲特":[["沃伦·巴菲特是著名的投资家。","ۋاررېن باففېت داڭلىق مەبلەغ سالغۇچى.","warrén baffét dangliq meblegh salghuchi."]],"没用":[["这个办法没用。","بۇ ئۇسۇلنىڭ پايدىسى يوق.","bu usulning paydisi yoq."]],"沙池":[["沙池是儿童游乐设施。","قۇم ئويمانچىسى بالىلار ئويۇن ئۈسكۈنىسى.","qum oymanchisi balilar oyun üskünisi."]],"沙和尚":[["沙和尚是唐僧的徒弟之一。","شا خېشاڭ تاڭ سەننىڭ شاگىرتلىرىنىڭ بىرى.","sha xéshang tang senning shagirtlirining biri."]],"泌乳":[["婴儿开始泌乳后，母亲感到轻松。","بوۋاق سۈت ئېمىشكە باشلىغاندىن كېيىن، ئانا ئۆزىنى يېنىك ھېس قىلدى.","bowaq süt émishke bashlighandin kéyin, ana özini yénik hés qildi."]],"泌阳":[["泌阳的特产很有名。","بىياڭيۇڭنىڭ ئالاھىدە مەھسۇلاتلىرى ناھايىتى داڭلىق.","biyangyungning alahide mehsulatliri nahayiti dangliq."]],"江南四大才子":[["江南四大才子的故事广为流传。","جياڭنەننىڭ تۆت ئۇلۇغ ئىستېدىنىڭ ھېكايىلىرى كەڭ تارقالغان.","jyangnenning töt ulugh istédining hékayiliri keng tarqalghan."]],"泉源":[["泉水的泉源深藏在山中。","بۇلاق سۈيىنىڭ مەنبەسى تاغ ئىچىدە يوشۇرۇنغان.","bulaq süyining menbesi tagh ichide yoshurunghan."]],"法兰克林":[["法兰克林是美国的开国元勋。","فاراڭكلىن ئامېرىكىنىڭ قۇرغۇچى ئاتىسى.","farangklin amérikining qurghuchi atisi."]],"波士尼亚":[["波士尼亚位于欧洲东南部。","بوسنىيە ياۋروپانىڭ جەنۇبىي شەرقىدە جايلاشقان.","bosniye yawropaning jenubiy sherqide jaylashqan."]],"沙里亚":[["沙里亚是伊斯兰教的法律体系。","شەرىئە ئىسلام دىنىنىڭ قانۇن سىستېمىسىدۇر.","sherie islam dinining qanun sistémisidur."]],"沙鼠":[["沙鼠是沙漠地区常见的啮齿动物。","قۇم چاشقانى چۆل رايونىدا كۆپ ئۇچرايدىغان كېمىرگۈچى ھايۋاندۇر.","qum chashqani chöl rayonida köp uchraydighan kémirgüchi haywandur."]],"泰加林":[["泰加林是寒带针叶林的统称。","تەيگا ئورمانلىقى سوغۇق بەلباغ ئىنچىكە يوپۇرماقلىق ئورمانلىقىنىڭ ئومۇمىي ئاتىلىشى.","teyga ormanliqi soghuq belbagh inchike yopurmaqliq ormanliqining omumiy atilishi."]],"泰北":[["泰北地区气候寒冷，植被稀疏。","تەي شىمالىي رايونىنىڭ ھاۋاسى سوغۇق، ئۆسۈملۈكلىرى شالاڭ.","tey shimaliy rayonining hawasi soghuq, ösümlükliri shalang."]],"泰坦巨龙":[["泰坦巨龙是恐龙家族中的巨无霸。","تىتانوزاۋر دىنوزاۋرلار ئائىلىسىدىكى ئەڭ زورى.","titanozawr dinozawrlar ailisidiki eng zori."]],"沾化县":[["沾化县以盐业闻名。","جەنخۇا ناھىيەسى تۇز سانائىتى بىلەن داڭلىق.","jenxua nahiyesi tuz sanaiti bilen dangliq."]],"泰米尔伊拉姆猛虎解放组织":[["泰米尔伊拉姆猛虎解放组织曾长期活跃于斯里兰卡。","تامىل ئىلام قاپلان ئازادلىق تەشكىلاتى ئۇزۇن مۇددەت سىرىلانكىدا ئاكتىپ بولغان.","tamil ilam qaplan azadliq teshkilati uzun muddet sirilankida aktip bolghan."]],"洋芋片":[["炸洋芋片外酥里嫩。","قورۇلغان ياڭيۇ پارچىلىرىنىڭ سىرتى خىرت، ئىچى يۇمشاق.","qorulghan yangyu parchilirining sirti xirt, ichi yumshaq."]],"洗涤间":[["洗涤间里放着清洁剂。","يۇيۇش ئۆيىدە تازىلاش سۇيۇقلۇقى قويۇلغان.","yuyush öyide tazilash suyuqluqi qoyulghan."]],"浣雪":[["浣雪比喻净化心灵。","قار يۇيۇش روھنى پاكلاشقا ئوخشىتىلىدۇ.","qar yuyush rohni paklashqa oxshitilidu."]],"海肠子":[["海肠子是一种可食用的海产。","دېڭىز ئۈچەيلىكى يېيىشكە بولىدىغان دېڭىز مەھسۇلاتى.","déngiz ücheyliki yéyishke bolidighan déngiz mehsulati."]],"清册":[["请核对清册上的信息。","تەكشۈرۈش تىزىملىكىدىكى ئۇچۇرلارنى سېلىشتۇرۇپ بېقىڭ.","tekshürüsh tizimlikidiki uchurlarni sélishturup béqing."]],"清洁球":[["清洁球能去除管道中的污垢。","تازىلاش شارى تۇرۇبا ئىچىدىكى كىرلەرنى يوقىتالايدۇ.","tazilash shari turuba ichidiki kirlerni yoqitalaydu."]],"涡桨":[["涡桨飞机适合短途飞行。","تۈرۈبىلىق پاراشوتلۇق ئايروپىلان قىسقا مۇساپىلىك ئۇچۇشقا ماس كېلىدۇ.","türübiliq parashotluq ayropilan qisqa musapilik uchushqa mas kélidu."]],"消费券":[["商场发放了购物消费券。","سودا سارىيى خېرىدارلارغا ئىستېمال قەغىزى تارقاتتى.","soda sariyi xéridarlargha istémal qeghizi tarqatti."]],"渭水":[["渭水发源于秦岭山脉。","ۋېيشۇي چىنلىڭ تاغ تىزمىسىدىن باشلىنىدۇ.","wéyshuy chinling tagh tizmisidin bashlinidu."]],"海难":[["海难事故令人痛心。","دېڭىز ئاپىتى كىشىنى قاتتىق ئەلەملەندۈرىدۇ.","déngiz apiti kishini qattiq elemlendüridu."]],"湘西":[["湘西地区风景优美。","شياڭشى رايونىنىڭ مەنزىرىسى گۈزەل.","shyangshi rayonining menzirisi güzel."]],"测谎仪":[["测谎仪通过生理信号判断说谎行为。","يالغان ئۆلچىگۈچ فىزىئولوگىيەلىك سىگنال ئارقىلىق يالغان سۆزلەش ھەرىكىتىنى ھۆكۈم قىلىدۇ.","yalghan ölchigüch fiziologiyelik signal arqiliq yalghan sözlesh herikitini höküm qilidu."]],"浑身解数":[["他使出了浑身解数。","ئۇ بارلىق كۈچ-قۇۋۋىتىنى ئىشلەتتى.","u barliq küch-quwwitini ishletti."]],"凑付":[["这工作只能凑付了事。","بۇ خىزمەتنى پەقەت ئامالسىز تۈگىتىشكە توغرا كېلىدۇ.","bu xizmetni peqet amalsiz tügitishke toghra kélidu."]],"源起":[["故事的源起令人好奇。","ھېكايىنىڭ مەنبەسى قىزىقارلىق.","hékayining menbesi qiziqarliq."]],"溪壑":[["溪壑深处隐藏着秘密。","ئېقىن ئېقىنىنىڭ چوڭقۇر يېرىدە سىر يوشۇرۇنغان.","éqin éqinining chongqur yéride sir yoshurunghan."]],"溺亡":[["溺亡是溺水导致的死亡。","غەرق بولۇپ ئۆلۈش سۇغا چۆكۈش سەۋەبىدىن كېلىپ چىققان ئۆلۈمدۇر.","gherq bolup ölüsh sugha chöküsh sewebidin kélip chiqqan ölümdur."]],"温室效应":[["温室效应会导致全球气温上升。","ئىسسىقخانا ئۈنۈمى پۈتۈن دۇنيا تېمپېراتۇرىسىنىڭ ئۆرلىشىگە سەۋەب بولىدۇ.","issiqxana ünümi pütün dunya témpératurisining örlishige seweb bolidu."]],"满门":[["满门英烈，整个家族都以爱国精神为荣。","پۈتۈن ئائىلە قەھرىمانلار بىلەن تولغان، پۈتۈن ئۇرۇق-تۇغقانلىرى ۋەتەنپەرۋەرلىك روھى بىلەن پەخىرلىنىدۇ.","pütün aile qehrimanlar bilen tolghan, pütün uruq-tughqanliri wetenperwerlik rohi bilen pexirlinidu."]],"汉民族":[["汉民族是中国主体民族。","خەنزۇ مىللىتى جۇڭگونىڭ ئاساسلىق مىللىتىدۇر.","xenzu milliti junggoning asasliq millitidur."]],"汉源":[["汉源是四川的一个著名产地。","خەنيۈەن سىچۇەندىكى بىر مەشھۇر ئىشلەپچىقىرىش جايىدۇر.","xenyüen sichuendiki bir meshhur ishlepchiqirish jayidur."]],"潭水":[["潭水清澈见底，十分美丽。","تاغ ئېقىنىنىڭ سۈيى تۇپ-تۇنۇق بولۇپ، ئاستى كۆرۈنۈپ تۇرىدۇ، ئىنتايىن گۈزەل.","tagh éqinining süyi tup-tunuq bolup, asti körünüp turidu, intayin güzel."]],"潮汕":[["潮汕地区以美食和方言著称。","چاۋشەن رايونى تائام ۋە شېۋە بىلەن داڭلىق.","chawshen rayoni taam we shéwe bilen dangliq."]],"潜逃":[["犯人潜逃后杳无音讯。","تۇتقۇن يوشۇرۇن قېچىپ كەتكەندىن كېيىن ھېچقانداق خەۋەر يوق.","tutqun yoshurun qéchip ketkendin kéyin héchqandaq xewer yoq."]],"澄海区":[["澄海区以海滨风光闻名。","چېڭخەي رايونى دېڭىز بويى مەنزىرىسى بىلەن داڭلىق.","chéngxey rayoni déngiz boyi menzirisi bilen dangliq."]],"卤蛋":[["卤蛋经过长时间炖煮，味道鲜美。","لۇۋ تۇخۇمى ئۇزۇن ۋاقىت قاينىتىلغاندىن كېيىن تەمى لەززەتلىك بولىدۇ.","luw tuxumi uzun waqit qaynitilghandin kéyin temi lezzetlik bolidu."]],"润发液":[["这款润发液含有天然成分。","بۇ نەملەندۈرۈش چاچ سۇيۇقلۇقى تەبىئىي تەركىبلەرنى ئۆز ئىچىگە ئالىدۇ.","bu nemlendürüsh chach suyuqluqi tebiiy terkiblerni öz ichige alidu."]],"润发露":[["润发露能减少头发打结。","نەملەندۈرۈش چاچ سۇيۇقلۇقى چاچنىڭ چىگىلىشىنى ئازايتالايدۇ.","nemlendürüsh chach suyuqluqi chachning chigilishini azaytalaydu."]],"滤清器":[["滤清器是汽车发动机的重要部件。","سۈزگۈچ ئاپتوموبىل ماتورىنىڭ مۇھىم زاپچاسلىرىنىڭ بىرى.","süzgüch aptomobil matorining muhim zapchaslirining biri."]],"灌阳":[["灌阳是广西的一个县。","گۇەنياڭ گۇاڭشىدىكى بىر ناھىيە.","guenyang guangshidiki bir nahiye."]],"沥水架":[["厨房的沥水架能让碗盘快速干燥。","ئاشخانىدىكى سۇ تامىزىدىغان رەت ئىدىشلارنى تېز قۇرۇتالايدۇ.","ashxanidiki su tamizidighan ret idishlarni téz qurutalaydu."]],"火色":[["她的发色呈现出独特的火色。","ئۇنىڭ چاچ رەڭگى ئالاھىدە ئوت رەڭگىنى ئەكس ئەتتۈرىدۇ.","uning chach renggi alahide ot renggini eks ettüridu."]],"灰林鸮":[["灰林鸮夜间在森林中捕食。","قۇمۇرەكلىك ئۇكە كېچىسى ئورماندا ئولجا تۇتىدۇ.","qumureklik uke kéchisi ormanda olja tutidu."]],"灰头鸫":[["灰头鸫经常出现在森林中。","كۈلرەڭ باشلىق زاغچە قۇش ئورمانلاردا كۆپ ئۇچرايدۇ.","külreng bashliq zaghche qush ormanlarda köp uchraydu."]],"灰头鹦鹉":[["灰头鹦鹉的羽毛色彩丰富。","كۈلرەڭ باشلىق تۇتى قۇشنىڭ پەيلىرى رەڭگارەڭ.","külreng bashliq tuti qushning peyliri renggareng."]],"烘焙师":[["这位烘焙师手艺精湛。","بۇ پىشۇرۇشچىنىڭ ھۈنەرى ئىنتايىن يۇقىرى.","bu pishurushchining hüneri intayin yuqiri."]],"无连接":[["这个设备支持无连接通信。","بۇ ئۈسكۈنە ئۇلانمىسىز ئالاقىنى قوللايدۇ.","bu üsküne ulanmisiz alaqini qollaydu."]],"煮法":[["这种煮法能让汤更鲜美。","بۇ قاينىتىش ئۇسۇلى شورپىنى تېخىمۇ لەززەتلىك قىلىدۇ.","bu qaynitish usuli shorpini téximu lezzetlik qilidu."]],"熄火":[["汽车突然熄火了，无法启动。","ماشىنا تۇيۇقسىز ئۆچۈپ قالدى، قوزغىتىشقا بولمىدى.","mashina tuyuqsiz öchüp qaldi, qozghitishqa bolmidi."]],"熊抱":[["她给了弟弟一个大大的熊抱。","ئۇ ئىنىسىغا چوڭ بىر ئېيىق قۇچاق ئاتتى.","u inisigha chong bir éyiq quchaq atti."]],"烟灰缸":[["烟灰缸里堆满了烟头，需要清理了。","تاماكا كۈلى قۇتىسى تاماكا باشلىرى بىلەن تولۇپ، تازىلاش كېرەك.","tamaka küli qutisi tamaka bashliri bilen tolup, tazilash kérek."]],"烧灼疼":[["感到烧灼疼。","كۆيگەن ئاغرىقنى ھېس قىلدىم.","köygen aghriqni hés qildim."]],"烧煮":[["把菜烧煮一下。","سېيىلارنى قاينىتىپ پىشۇرۇڭ.","séyilarni qaynitip pishurung."]],"烫衣板":[["烫衣板是熨衣工具。","كىيىم دەملەش تاختىسى دەملەش قورالىدۇر.","kiyim demlesh taxtisi demlesh qoralidur."]],"焚毁":[["焚毁指将物品彻底烧毁。","كۆيدۈرۈپ يوق قىلىش بۇيۇملارنى پۈتۈنلەي كۆيدۈرۈپ يوق قىلىشنى كۆرسىتىدۇ.","köydürüp yoq qilish buyumlarni pütünley köydürüp yoq qilishni körsitidu."]],"牙冠":[["牙冠保护着牙齿的内部结构。","چىش تاجى چىشنىڭ ئىچكى قۇرۇلمىسىنى قوغدايدۇ.","chish taji chishning ichki qurulmisini qoghdaydu."]],"牛膝草":[["牛膝草常被用来泡茶。","كالا تىزىسى ئوتى كۆپىنچە چاي دەملەشتە ئىشلىتىلىدۇ.","kala tizisi oti köpinche chay demleshte ishlitilidu."]],"争夺战":[["这场比赛是一场激烈的争夺战。","بۇ مۇسابىقە شىددەتلىك تالاش-تارتىش جېڭىدۇر.","bu musabiqe shiddetlik talash-tartish jéngidur."]],"狐鬼神仙":[["故事里出现了狐鬼神仙。","ھېكايىدە تۈلكە ئالۋاستى پەرىشتە پەيدا بولدى.","hékayide tülke alwasti perishte peyda boldi."]],"特异功能":[["他拥有特异功能。","ئۇ ئالاھىدە قابىلىيەتكە ئىگە.","u alahide qabiliyetke ige."]],"狎昵":[["两人之间过于狎昵，令人不适。","ئىككىيلەن ئارىسىدىكى مۇناسىۋەت بەكلا يېقىن بولۇپ، كىشىنى بىئارام قىلىدۇ.","ikkiylen arisidiki munasiwet bekla yéqin bolup, kishini biaram qilidu."]],"牡丹江":[["牡丹江是黑龙江省的河流。","مۇدىن جياڭ خېيلۇڭجياڭ ئۆلكىسىنىڭ دەرياسى.","mudin jyang xéylungjyang ölkisining deryasi."]],"玉米花":[["玉米花爆开后非常酥脆可口。","قوناق پۈتۈكى پارتلىغاندىن كېيىن ئىنتايىن غىدىق ۋە لەززەتلىك بولىدۇ.","qonaq pütüki partlighandin kéyin intayin ghidiq we lezzetlik bolidu."]],"兽脚类恐龙":[["兽脚类恐龙是食肉动物。","تېروپود دىنوزاۋرلار گۆشخور ھايۋانلاردۇر.","téropod dinozawrlar göshxor haywanlardur."]],"甄别":[["需要仔细甄别真假。","ھەقىقىي ۋە يالغاننى ئېنىق پەرقلەندۈرۈش كېرەك.","heqiqiy we yalghanni éniq perqlendürüsh kérek."]],"甘井子区":[["甘井子区是大连市的一个行政区。","گەنجىڭزى رايونى داليەن شەھىرىنىڭ بىر مەمۇرىي رايونىدۇر.","genjingzi rayoni dalyen shehirining bir memuriy rayonidur."]],"班达亚齐":[["班达亚齐是印度尼西亚的一座重要城市。","باندا ئاچېھ ئىندونېزىيەدىكى مۇھىم بىر شەھەر.","banda achéh indonéziyediki muhim bir sheher."]],"生卒年月":[["记录生卒年月很重要。","تۇغۇلغان ۋە ئۆلگەن يىل-ئېيىنى خاتىرىلەش ئىنتايىن مۇھىم.","tughulghan we ölgen yil-éyini xatirilesh intayin muhim."]],"田长霖":[["田长霖是一位著名的企业家。","دېڭىز چاڭلىن مەشھۇر تىجارەتچى.","déngiz changlin meshhur tijaretchi."]],"申论":[["申论考试要求逻辑严密。","شېنلۇن ئىمتىھانى لوگىكىلىق جەھەتتىن قاتتىق بولۇشىنى تەلەپ قىلىدۇ.","shénlun imtihani logikiliq jehettin qattiq bolushini telep qilidu."]],"男友力":[["他的男友力让女友很安心。","ئۇنىڭ ئەرلىك كۈچى قىز دوستىنى ئىنتايىن خاتىرجەم قىلدى.","uning erlik küchi qiz dostini intayin xatirjem qildi."]],"用量":[["请按照说明控制用量。","ئىشلىتىش مىقدارىنى چۈشەندۈرۈشكە ئاساسەن كونترول قىلىڭ.","ishlitish miqdarini chüshendürüshke asasen kontrol qiling."]],"界河":[["界河是两国之间共同使用的河流。","چېگرا دەرياسى ئىككى دۆلەت ئارىسىدا ئورتاق ئىشلىتىلىدىغان دەريادىدۇر.","chégra deryasi ikki dölet arisida ortaq ishlitilidighan deryadidur."]],"留传":[["这技艺留传至今。","بۇ ھۈنەر بۈگۈنگىچە داۋاملىشىپ كەلدى.","bu hüner bügüngiche dawamliship keldi."]],"病菌":[["病菌会通过空气传播，引发感染。","كېسەللىك مىكروبتىرى ھاۋا ئارقىلىق تارقىلىپ، يۇقۇم پەيدا قىلىدۇ.","késellik mikrobtiri hawa arqiliq tarqilip, yuqum peyda qilidu."]],"疣猪":[["这种疣猪生活在非洲草原。","بۇ خىل سۆگەللىك توڭگۇز ئافرىقا يايلاقلىرىدا ياشايدۇ.","bu xil sögellik tongguz afriqa yaylaqlirida yashaydu."]],"当晚":[["当晚他们一起看了电影。","ئۇلار شۇ كېچىدە بىرلىكتە كىنو كۆردى.","ular shu kéchide birlikte kino kördi."]],"白头鹞":[["白头鹞擅长在空中捕猎。","ئاق باشلىق قۇيغۇن ھاۋادا ئوۋ ئوۋلاشقا ماھىر.","aq bashliq quyghun hawada ow owlashqa mahir."]],"白鹄":[["白鹄是一种优雅的水鸟。","ئاق ئاققۇش نەپىس سۇ قۇشى.","aq aqqush nepis su qushi."]],"白眉地鸫":[["白眉地鸫是一种小型鸟类。","ئاق قاش تۇردى بىر خىل كىچىك قۇش.","aq qash turdi bir xil kichik qush."]],"礌石":[["礌石是一种古老的磨石工具。","لېيشى قەدىمكى زامانلاردا ئىشلىتىلگەن بىر خىل ئېغىرلىق تاش قورالى.","léyshi qedimki zamanlarda ishlitilgen bir xil éghirliq tash qorali."]],"短靴":[["她穿了一双短靴。","ئۇ بىر جۈپ قىسقا ئۆتۈك كىيىۋالغان.","u bir jüp qisqa ötük kiyiwalghan."]],"研究报告":[["这份研究报告分析了市场趋势。","بۇ تەتقىقات دوكلاتى بازار يۈزلىنىشىنى تەھلىل قىلدى.","bu tetqiqat doklati bazar yüzlinishini tehlil qildi."]],"社群媒体":[["社群媒体改变了信息传播方式。","ئىجتىمائىي تاراتقۇ ئۇچۇر تارقىتىش ئۇسۇلىنى ئۆزگەرتتى.","ijtimaiy taratqu uchur tarqitish usulini özgertti."]],"竹简":[["竹简是古代书写文字的重要载体。","بامبۇك تاۋاقچىسى قەدىمكى زاماندا خەت يېزىشنىڭ مۇھىم تەشۈكچىسى.","bambuk tawaqchisi qedimki zamanda xet yézishning muhim teshükchisi."]],"细语":[["他低声细语，生怕打扰到别人。","ئۇ باشقىلارغا ئاۋارە بولۇپ قالماسلىق ئۈچۈن پەس ئاۋازدا پىچىرلىدى.","u bashqilargha aware bolup qalmasliq üchün pes awazda pichirlidi."]],"索然无味":[["这道菜的味道索然无味，毫无吸引力。","بۇ تاماقنىڭ تەمى بىھۇدە، ھېچقانداق جەلپ قىلىش كۈچى يوق.","bu tamaqning temi bihude, héchqandaq jelp qilish küchi yoq."]],"纸烟":[["纸烟的尼古丁含量较高。","قەغەز تاماكىنىڭ نىكوتىن مىقدارى يۇقىرى.","qeghez tamakining nikotin miqdari yuqiri."]],"结党":[["他因结党营私被开除。","ئۇ گۇرۇھچىلىق قىلىپ شەخسىي مەنپەئەت كۆزلەپ خىزمەتتىن چىقىرىۋېتىلدى.","u guruhchiliq qilip shexsiy menpeet közlep xizmettin chiqiriwétildi."]]};
